(function () {
  var OR = (window.OR = window.OR || {}); OR.qa = OR.qa || [];
  OR.qa.push(
    {"id": "pylib-counter-count", "title": "Count occurrences with collections.Counter", "q": ["how do i count how many times each item appears in python", "python counter", "count frequency of elements in a list", "character frequency of a string python", "collections.Counter example"], "tags": "counter collections frequency count occurrences hashmap histogram", "a": "Wrap any iterable in `Counter(...)`. It is a dict subclass mapping item to count, and a missing key reads as 0 (without being inserted).", "code": {"py": "from collections import Counter\nc = Counter(\"banana\")\nprint(c)            # Counter({'a': 3, 'n': 2, 'b': 1})\nprint(c[\"a\"], c[\"z\"])   # 3 0\nc[\"z\"] += 1         # works without initialising\nprint(sum(c.values()), len(c))"}, "more": "- Building it is O(n).\n- `c.total()` (3.10+) sums all counts; `sum(c.values())` works everywhere.\n- Reading a missing key does not add it; `c[k] += 1` does.", "cx": "Build O(n), lookup O(1) average", "see": ["#/topic/arrays-hashing", "#/cheatsheets/python"], "check": "assert c[\"a\"]==3 and c[\"q\"]==0 and \"q\" not in c\nassert Counter([])==Counter()\nassert Counter([1,1,2])[1]==2"},
    {"id": "pylib-counter-most-common", "title": "Get the most common elements (Counter.most_common)", "q": ["how to find the most frequent element in a list python", "most_common", "top k frequent elements using counter", "find the mode of a list in python", "get the element that appears most often"], "tags": "counter most_common frequent mode top k frequency", "a": "`Counter(items).most_common(k)` returns the k highest-count `(item, count)` pairs, largest first. With no argument it returns all items sorted by count. Ties keep first-encountered order.", "code": {"py": "from collections import Counter\nwords = [\"a\", \"b\", \"a\", \"c\", \"b\", \"a\"]\nc = Counter(words)\nprint(c.most_common(2))        # [('a', 3), ('b', 2)]\ntop = c.most_common(1)[0][0]   # the mode\nprint(top)                     # a\nprint([x for x, _ in c.most_common()])"}, "more": "- With k given it uses `heapq.nlargest`, about O(n log k); with no k it fully sorts, O(n log n).\n- For top-k frequent in an interview, bucket sort by count gives O(n).", "cx": "O(n log k) for most_common(k)", "see": ["#/topic/arrays-hashing", "#/topic/heaps"], "check": "assert c.most_common(2)==[(\"a\",3),(\"b\",2)]\nassert top==\"a\"\nassert Counter().most_common(1)==[]"},
    {"id": "pylib-counter-arith", "title": "Add, subtract and compare Counters", "q": ["counter arithmetic python", "subtract two counters", "check if one counter contains another", "merge counts of two dictionaries", "counter update vs subtract", "multiset operations python"], "tags": "counter subtract update add multiset intersection union & |", "a": "Counters support `+` (add counts), `-` (subtract, dropping results <= 0), `&` (min of counts) and `|` (max of counts). `update` adds in place and `subtract` subtracts in place, keeping zero and negative counts.", "code": {"py": "from collections import Counter\na = Counter(\"aabbc\"); b = Counter(\"abd\")\nprint(a + b)      # a:3 b:3 c:1 d:1\nprint(a - b)      # a:1 b:1 c:1  (d dropped)\nprint(a & b)      # a:1 b:1\nprint(a | b)      # a:2 b:2 c:1 d:1\na.subtract(b)\nprint(a[\"d\"])     # -1 (kept)\nneed, have = Counter(\"aab\"), Counter(\"aabbc\")\nprint(not (need - have))   # True: have covers need"}, "more": "- `not (need - have)` is the idiom for \"can I build need from have\" (ransom note).\n- Unary `+c` strips zero and negative counts.", "cx": "O(number of distinct keys)", "see": ["#/cheatsheets/python"], "check": "assert (Counter(\"aabbc\")-Counter(\"abd\"))==Counter(\"abc\")\nassert a[\"d\"]==-1\nassert not (need-have) and (Counter(\"aaa\")-have)"},
    {"id": "pylib-counter-anagram", "title": "Check for anagrams with Counter", "q": ["how to check if two strings are anagrams in python", "anagram check", "group anagrams python", "are two words anagrams", "compare letter counts of two strings"], "tags": "anagram counter sorted group anagrams defaultdict string", "a": "Two strings are anagrams if their letter counts match: `Counter(s) == Counter(t)` (O(n)) or `sorted(s) == sorted(t)` (O(n log n)). To group many words, use the sorted word, or a count tuple, as a dict key.", "code": {"py": "from collections import Counter, defaultdict\n\ndef is_anagram(s, t):\n    return Counter(s) == Counter(t)\n\ndef group_anagrams(words):\n    groups = defaultdict(list)\n    for w in words:\n        groups[\"\".join(sorted(w))].append(w)\n    return list(groups.values())\n\nprint(is_anagram(\"listen\", \"silent\"))   # True\nprint(group_anagrams([\"eat\", \"tea\", \"tan\", \"ate\", \"nat\"]))"}, "more": "- For lowercase letters only, a 26-length count tuple as the key makes grouping O(n*k) instead of O(n*k log k).\n- Different lengths can never be anagrams: check `len` first for a quick exit.", "cx": "Counter compare O(n); grouping O(n k log k)", "see": ["#/topic/arrays-hashing"], "check": "assert is_anagram(\"listen\",\"silent\") and not is_anagram(\"a\",\"b\") and is_anagram(\"\",\"\")\ng=group_anagrams([\"eat\",\"tea\",\"tan\",\"ate\",\"nat\"])\nassert sorted(map(sorted,g))==[[\"ate\",\"eat\",\"tea\"],[\"nat\",\"tan\"]]"},
    {"id": "pylib-defaultdict-list", "title": "defaultdict(list): group items by key", "q": ["python defaultdict", "how to append to a dict of lists without checking key", "group values by key in python", "defaultdict list example", "avoid keyerror when appending"], "tags": "defaultdict collections group by list dict default factory keyerror", "a": "`defaultdict(list)` creates an empty list the first time you read a missing key, so you can `d[k].append(v)` with no `if k in d`. The argument is a zero-argument factory.", "code": {"py": "from collections import defaultdict\npairs = [(\"a\", 1), (\"b\", 2), (\"a\", 3)]\nd = defaultdict(list)\nfor k, v in pairs:\n    d[k].append(v)\nprint(dict(d))     # {'a': [1, 3], 'b': [2]}\nprint(d[\"zzz\"])    # [] and the key is now inserted!"}, "more": "- Reading a missing key inserts it. Use `k in d` or `d.get(k)` when you must not create entries.\n- Plain-dict alternative: `d.setdefault(k, []).append(v)`.", "cx": "O(1) average per access", "see": ["#/topic/arrays-hashing"], "check": "assert dict(defaultdict(list))=={}\nassert d[\"a\"]==[1,3]\nassert \"zzz\" in d\nassert \"nope\" not in d"},
    {"id": "pylib-defaultdict-int-set", "title": "defaultdict(int) and defaultdict(set)", "q": ["defaultdict int counting", "defaultdict set example", "count with defaultdict", "dict that defaults to zero", "dedupe values per key"], "tags": "defaultdict int set counting default zero factory unique values", "a": "`defaultdict(int)` starts every missing key at 0, handy for counting. `defaultdict(set)` starts at an empty set, for unique values per key. Any callable works, e.g. `defaultdict(lambda: -1)`.", "code": {"py": "from collections import defaultdict\ncnt = defaultdict(int)\nfor ch in \"hello\":\n    cnt[ch] += 1\nprint(dict(cnt))        # {'h': 1, 'e': 1, 'l': 2, 'o': 1}\n\nseen = defaultdict(set)\nfor k, v in [(\"x\", 1), (\"x\", 1), (\"x\", 2)]:\n    seen[k].add(v)\nprint(seen[\"x\"])        # {1, 2}\n\nneg = defaultdict(lambda: -1)\nprint(neg[\"q\"])         # -1"}, "more": "- `Counter` is better when you also want `most_common` or arithmetic.", "see": ["#/cheatsheets/python"], "check": "assert cnt[\"l\"]==2 and seen[\"x\"]=={1,2} and neg[\"q\"]==-1"},
    {"id": "pylib-defaultdict-graph", "title": "Build a graph adjacency list with defaultdict", "q": ["how to represent a graph in python", "build adjacency list from edge list", "graph adjacency list defaultdict", "undirected graph from edges python", "edge list to adjacency list"], "tags": "graph adjacency list defaultdict edges undirected directed build", "a": "Loop over the edge list and append to `graph[u]` (and `graph[v]` if undirected) using `defaultdict(list)`. Nodes with no edges will not appear unless you add them.", "code": {"py": "from collections import defaultdict\n\ndef build_graph(n, edges, directed=False):\n    g = defaultdict(list)\n    for u, v in edges:\n        g[u].append(v)\n        if not directed:\n            g[v].append(u)\n    return [g[i] for i in range(n)]   # list of lists, includes isolated nodes\n\nadj = build_graph(4, [(0, 1), (1, 2)])\nprint(adj)   # [[1], [0, 2], [1], []]"}, "more": "- For weighted edges store `(neighbor, weight)` tuples.\n- If nodes are numbered 0..n-1, `[[] for _ in range(n)]` works with no import (do not use `[[]] * n`).", "cx": "O(V + E)", "see": ["#/topic/graphs", "#/cheatsheets/graphs"], "check": "assert adj==[[1],[0,2],[1],[]]\nassert build_graph(2,[(0,1)],True)==[[1],[]]\nassert build_graph(1,[])==[[]]"},
    {"id": "pylib-deque-queue", "title": "Use a deque as a queue", "q": ["how to implement a queue in python", "python queue collections deque", "fifo queue python", "popleft", "best queue for bfs python"], "tags": "deque queue fifo popleft append collections bfs", "a": "Use `collections.deque`: `append(x)` to enqueue and `popleft()` to dequeue, both O(1). Do not use a list for this, since `list.pop(0)` is O(n).", "code": {"py": "from collections import deque\nq = deque()\nq.append(1); q.append(2); q.append(3)\nprint(q.popleft())    # 1\nprint(q[0], len(q))   # 2 2  (peek front)\nprint(bool(q))        # True; empty deque is falsy\nq2 = deque([1, 2, 3])   # build from a list"}, "more": "- `popleft()` on an empty deque raises `IndexError`; test `while q:` first.\n- Indexing in the middle is O(n); the ends are O(1).", "cx": "append/popleft O(1)", "see": ["#/topic/queues"], "check": "assert list(q)==[2,3]\nassert q.popleft()==2\nassert list(q2)==[1,2,3]\ntry:\n    deque().popleft(); assert False\nexcept IndexError: pass"},
    {"id": "pylib-deque-vs-list-pop0", "title": "deque.popleft() vs list.pop(0)", "q": ["why is list.pop(0) slow", "list pop(0) complexity", "popleft vs pop(0)", "is deque faster than list in python", "remove first element of list efficiently"], "tags": "deque popleft pop(0) list complexity slow shift queue", "a": "`list.pop(0)` is O(n) because every remaining element shifts left; `deque.popleft()` is O(1). Use a deque whenever you remove from the front repeatedly (BFS, sliding window).", "code": {"py": "from collections import deque\nimport time\n\ndef drain_list(n):\n    a = list(range(n))\n    while a:\n        a.pop(0)\n\ndef drain_deque(n):\n    d = deque(range(n))\n    while d:\n        d.popleft()\n\nt = time.perf_counter(); drain_list(50000); t1 = time.perf_counter() - t\nt = time.perf_counter(); drain_deque(50000); t2 = time.perf_counter() - t\nprint(t1 > t2)   # True on any normal machine"}, "more": "- Alternative for lists: keep a head index instead of popping (read `a[i]`, then `i += 1`).\n- Same cost story for `list.insert(0, x)` vs `deque.appendleft(x)`.", "cx": "list.pop(0) O(n); deque.popleft() O(1)", "see": ["#/topic/queues", "#/cheatsheets/big-o-algorithms"], "check": "a=[1,2,3]; assert a.pop(0)==1 and a==[2,3]\nassert t2 < t1"},
    {"id": "pylib-deque-maxlen", "title": "deque with maxlen (fixed-size window)", "q": ["keep only the last n items python", "deque maxlen", "sliding window of last k elements", "circular buffer python", "bounded queue python"], "tags": "deque maxlen bounded circular buffer last k recent window", "a": "Pass `maxlen=k` and the deque drops from the opposite end when full, so it always holds the latest k items. Appends stay O(1).", "code": {"py": "from collections import deque\nlast3 = deque(maxlen=3)\nfor x in range(6):\n    last3.append(x)\nprint(last3)        # deque([3, 4, 5], maxlen=3)\nprint(last3.maxlen) # 3"}, "more": "- `appendleft` on a full deque drops from the right end.\n- Handy for \"last N lines\" and moving averages.", "cx": "O(1) per append", "see": ["#/cheatsheets/python"], "check": "assert list(last3)==[3,4,5]\nd=deque([1,2],maxlen=2); d.appendleft(0); assert list(d)==[0,1]"},
    {"id": "pylib-deque-rotate", "title": "Rotate a deque (or a list) by k", "q": ["rotate a list in python", "deque rotate", "rotate array by k steps", "shift list elements to the right", "rotate list left python"], "tags": "deque rotate list rotation shift k steps slicing", "a": "`d.rotate(k)` rotates right by k (negative k rotates left), in place, O(k). For a plain list use slicing: `a[-k:] + a[:-k]` for a right rotation (take `k %= len(a)` first).", "code": {"py": "from collections import deque\nd = deque([1, 2, 3, 4, 5])\nd.rotate(2)\nprint(list(d))      # [4, 5, 1, 2, 3]\nd.rotate(-2)\nprint(list(d))      # [1, 2, 3, 4, 5]\n\ndef rotate_right(a, k):\n    if not a:\n        return a\n    k %= len(a)\n    return a[-k:] + a[:-k] if k else a[:]\n\nprint(rotate_right([1, 2, 3, 4, 5], 2))   # [4, 5, 1, 2, 3]"}, "more": "- `a[-0:]` is the whole list, which is why `k == 0` is special-cased.\n- The in-place O(1)-space version uses three reversals.", "see": ["#/topic/arrays-hashing"], "check": "assert rotate_right([1,2,3,4,5],7)==[4,5,1,2,3]\nassert rotate_right([],3)==[] and rotate_right([1,2],0)==[1,2]\nassert list(d)==[1,2,3,4,5]"},
    {"id": "pylib-deque-stack", "title": "Stack in Python: list vs deque", "q": ["how to implement a stack in python", "python stack push pop", "use list as a stack", "stack with deque", "peek top of stack python"], "tags": "stack list append pop peek lifo deque", "a": "Use a plain list: `append` to push, `pop()` to pop, `s[-1]` to peek, all O(1) amortized. A deque also works. Check emptiness with `if s:` before popping or peeking.", "code": {"py": "s = []\ns.append(1); s.append(2); s.append(3)\nprint(s[-1])     # 3 peek\nprint(s.pop())   # 3\nprint(s)         # [1, 2]\nprint(not s)     # False -> not empty\n\ndef balanced(text):\n    pairs = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\n    st = []\n    for ch in text:\n        if ch in \"([{\":\n            st.append(ch)\n        elif ch in pairs:\n            if not st or st.pop() != pairs[ch]:\n                return False\n    return not st"}, "more": "- `pop()` on an empty list raises `IndexError`.\n- Do not use `list.pop(0)`/`insert(0, x)` for a stack; push and pop at the end.", "cx": "push/pop O(1) amortized", "see": ["#/topic/stacks"], "check": "assert s==[1,2]\nassert balanced(\"([]{})\") and not balanced(\"(]\") and not balanced(\"(\") and balanced(\"\")"},
    {"id": "pylib-ordereddict-lru", "title": "LRU cache with OrderedDict (move_to_end)", "q": ["implement lru cache in python", "ordereddict move_to_end", "python lru cache from scratch", "least recently used cache popitem", "lru cache O(1) get put"], "tags": "lru cache ordereddict move_to_end popitem least recently used design", "a": "Keep entries in an `OrderedDict`. On `get`/`put` call `move_to_end(key)` to mark it newest; when over capacity call `popitem(last=False)` to evict the oldest. Both are O(1).", "code": {"py": "from collections import OrderedDict\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.cap = capacity\n        self.d = OrderedDict()\n\n    def get(self, key):\n        if key not in self.d:\n            return -1\n        self.d.move_to_end(key)\n        return self.d[key]\n\n    def put(self, key, value):\n        if key in self.d:\n            self.d.move_to_end(key)\n        self.d[key] = value\n        if len(self.d) > self.cap:\n            self.d.popitem(last=False)\n\nc = LRUCache(2)\nc.put(1, 1); c.put(2, 2); c.get(1); c.put(3, 3)\nprint(c.get(2))   # -1 (evicted)"}, "more": "- Plain dicts also keep insertion order, but have no `move_to_end`; OrderedDict does.\n- Interviews may ask for the hash map + doubly linked list version instead.", "cx": "get/put O(1)", "see": ["#/topic/design-ds", "#/problem/146"], "check": "assert c.get(2)==-1 and c.get(1)==1 and c.get(3)==3\nc2=LRUCache(1); c2.put(1,1); c2.put(1,5); assert c2.get(1)==5; c2.put(2,2); assert c2.get(1)==-1"},
    {"id": "pylib-namedtuple", "title": "namedtuple: lightweight record type", "q": ["python namedtuple", "how to create a simple struct in python", "namedtuple vs dataclass", "tuple with field names", "named fields for tuples"], "tags": "namedtuple collections struct record tuple field name dataclass", "a": "`namedtuple(\"Point\", \"x y\")` creates a tuple subclass with named fields. It is immutable, hashable (usable as dict key or set member) and unpacks like a tuple. Use `_replace` to make a modified copy.", "code": {"py": "from collections import namedtuple\nPoint = namedtuple(\"Point\", [\"x\", \"y\"])\np = Point(1, 2)\nprint(p.x, p[1])         # 1 2\nx, y = p                 # unpacking works\nprint(p._replace(x=9))   # Point(x=9, y=2)\nseen = {p}               # hashable\nprint(Point(1, 2) in seen)   # True"}, "more": "- Need mutability or defaults/methods? Use `@dataclass`.\n- Tuples compare lexicographically, so namedtuples sort and work in heaps.", "see": ["#/cheatsheets/python"], "check": "assert p==(1,2) and Point(1,2) in seen and p._replace(y=0)==Point(1,0)\ntry:\n    p.x=3; assert False\nexcept AttributeError: pass"},
    {"id": "pylib-heapq-basics", "title": "heapq: min-heap push, pop, peek", "q": ["how to use a heap in python", "python priority queue", "heapq example", "heappush heappop", "min heap in python", "get the smallest element repeatedly"], "tags": "heapq heap priority queue min heap heappush heappop peek", "a": "`heapq` turns a plain list into a min-heap. `heappush(h, x)` adds, `heappop(h)` removes and returns the smallest, and `h[0]` peeks at the smallest. Push/pop are O(log n), peek is O(1).", "code": {"py": "import heapq\nh = []\nfor x in [5, 1, 4, 2]:\n    heapq.heappush(h, x)\nprint(h[0])               # 1 (peek)\nprint(heapq.heappop(h))   # 1\nprint(heapq.heappop(h))   # 2\nprint(len(h))             # 2\n# only h[0] is guaranteed to be the min; the rest of the list is not sorted"}, "more": "- `heappop` on an empty list raises `IndexError`; guard with `if h:`.\n- Python has no max-heap class; negate values (see the max-heap entry).\n- `heapq` is not thread-safe; for threads use `queue.PriorityQueue`.", "cx": "push/pop O(log n), peek O(1)", "see": ["#/topic/heaps"], "check": "assert h[0]==4 and len(h)==2\nassert heapq.heappop(h)==4 and heapq.heappop(h)==5\ntry:\n    heapq.heappop(h); assert False\nexcept IndexError: pass"},
    {"id": "pylib-heapq-max-heap", "title": "Max-heap in Python (negate values)", "q": ["how to make a max heap in python", "heapq max heap", "python priority queue largest first", "heap largest element first", "negative numbers trick heap"], "tags": "max heap heapq negate negative largest first priority", "a": "heapq is min-only, so push the negated value and negate again when you pop: `heappush(h, -x)`, `-heappop(h)`. The largest value is `-h[0]`.", "code": {"py": "import heapq\nh = []\nfor x in [3, 9, 4]:\n    heapq.heappush(h, -x)\nprint(-h[0])              # 9 (peek max)\nprint(-heapq.heappop(h))  # 9\nprint(-heapq.heappop(h))  # 4\n\n# for tuples, negate the numeric key: (-priority, item)\njobs = []\nheapq.heappush(jobs, (-5, \"low\"))\nheapq.heappush(jobs, (-9, \"urgent\"))\nprint(heapq.heappop(jobs)[1])   # urgent"}, "more": "- Negation only works for numbers. For strings or objects, define `__lt__` on a wrapper class.\n- Remember to negate on the way in and on the way out.", "cx": "O(log n) push/pop", "see": ["#/topic/heaps"], "check": "assert -h[0]==3\nassert heapq.heappop(jobs)==(-5,\"low\")"},
    {"id": "pylib-heapq-heapify", "title": "Turn a list into a heap (heapify)", "q": ["heapify python", "build a heap from a list", "heapq.heapify complexity", "convert list to min heap", "is heapify O(n)"], "tags": "heapify build heap list in place linear", "a": "`heapq.heapify(lst)` rearranges the list into a min-heap in place in O(n). That is faster than pushing n items one by one, which costs O(n log n).", "code": {"py": "import heapq\nnums = [9, 4, 7, 1, 8]\nheapq.heapify(nums)\nprint(nums[0])    # 1\nout = [heapq.heappop(nums) for _ in range(len(nums))]\nprint(out)        # [1, 4, 7, 8, 9]  (heap sort)"}, "more": "- It modifies the list in place and returns None.\n- Heap sort in two lines is O(n log n) but needs a copy if you want to keep the original.", "cx": "heapify O(n)", "see": ["#/topic/heaps"], "check": "assert out==[1,4,7,8,9]\nl=[]; heapq.heapify(l); assert l==[]"},
    {"id": "pylib-heapq-nlargest", "title": "heapq.nlargest and nsmallest", "q": ["get the k largest elements in python", "heapq nlargest", "top 3 items of a list", "k smallest elements python", "nlargest with key"], "tags": "nlargest nsmallest heapq top k largest smallest key", "a": "`heapq.nlargest(k, iterable, key=None)` returns the k biggest items, largest first; `nsmallest` returns the k smallest, smallest first. It is O(n log k), better than sorting everything when k is small.", "code": {"py": "import heapq\nnums = [5, 1, 9, 3, 7]\nprint(heapq.nlargest(2, nums))     # [9, 7]\nprint(heapq.nsmallest(2, nums))    # [1, 3]\nwords = [\"pear\", \"fig\", \"banana\"]\nprint(heapq.nlargest(1, words, key=len))   # ['banana']"}, "more": "- If k is close to n, `sorted(...)[:k]` is as fast or faster.\n- For k = 1 use `max`/`min`.", "cx": "O(n log k)", "see": ["#/topic/heaps"], "check": "assert heapq.nlargest(2,nums)==[9,7]\nassert heapq.nsmallest(0,nums)==[]\nassert heapq.nlargest(10,nums)==sorted(nums,reverse=True)"},
    {"id": "pylib-heapq-pushpop", "title": "heappushpop vs heapreplace", "q": ["heapq heappushpop", "heapreplace vs heappushpop", "keep a heap of fixed size k", "push then pop in one operation", "difference between heapreplace and heappush"], "tags": "heappushpop heapreplace heapq fixed size k replace smallest", "a": "`heappushpop(h, x)` pushes x then pops the smallest (so x itself comes back if it is smaller). `heapreplace(h, x)` pops the smallest first, then pushes x (the heap must be non-empty). Both are faster than two separate calls.", "code": {"py": "import heapq\nh = [3, 5, 8]\nheapq.heapify(h)\nprint(heapq.heappushpop(h, 1))   # 1  (x was smallest, heap unchanged)\nprint(heapq.heappushpop(h, 4))   # 3\nprint(heapq.heapreplace(h, 0))   # 4  (popped first, then 0 pushed)\nprint(h[0])                      # 0"}, "more": "- Key difference: heapreplace can return a value larger than x; heappushpop never does.\n- Typical use: keep the k largest by `heappushpop` onto a size-k min-heap.", "cx": "O(log n)", "see": ["#/topic/heaps"], "check": "assert sorted(h)==[0,5,8]"},
    {"id": "pylib-heapq-tuples", "title": "Heap of tuples (priority, item)", "q": ["heapq with tuples", "priority queue with priorities python", "how does heapq compare tuples", "heap of (distance, node)", "heapq tie breaking error not supported between"], "tags": "heapq tuple priority queue dijkstra tie break comparison counter", "a": "Push `(priority, item)` tuples: heapq compares tuples element by element, so the smallest priority pops first. If priorities can tie and items are not comparable, add a unique counter as the middle element.", "code": {"py": "import heapq, itertools\nh = []\nheapq.heappush(h, (2, \"b\"))\nheapq.heappush(h, (1, \"z\"))\nheapq.heappush(h, (1, \"a\"))\nprint(heapq.heappop(h))   # (1, 'a')  ties break on the next element\n\n# non-comparable payloads: tie-break with a counter\ntie = itertools.count()\npq = []\nheapq.heappush(pq, (1, next(tie), {\"k\": 1}))\nheapq.heappush(pq, (1, next(tie), {\"k\": 2}))   # no dict comparison needed\nprint(heapq.heappop(pq)[2])   # {'k': 1}  (FIFO among ties)"}, "more": "- Without the counter, equal priorities make Python compare the dicts and raise `TypeError`.\n- Dijkstra pushes `(dist, node)`; nodes are ints so ties are safe.", "see": ["#/topic/heaps", "#/topic/shortest-paths"], "check": "assert heapq.heappop(h)==(1,\"z\")\nassert heapq.heappop(pq)[2]=={\"k\":2}"},
    {"id": "pylib-heapq-custom-class", "title": "Heap with custom ordering (class or key)", "q": ["heapq custom comparator", "heap of objects python", "define __lt__ for heapq", "sort heap by custom key", "heapq with key function"], "tags": "heapq custom comparator __lt__ objects key order dataclass", "a": "heapq has no `key` argument for push/pop. Either push tuples `(key, obj)`, or give the class `__lt__` (heapq only uses `<`). A dataclass with `order=True` also works and compares by field order.", "code": {"py": "import heapq\nfrom dataclasses import dataclass, field\n\nclass Task:\n    def __init__(self, name, pri):\n        self.name, self.pri = name, pri\n    def __lt__(self, other):\n        return self.pri > other.pri      # bigger pri pops first\n\nh = [Task(\"a\", 1), Task(\"b\", 5)]\nheapq.heapify(h)\nprint(heapq.heappop(h).name)   # b\n\n@dataclass(order=True)\nclass Job:\n    cost: int\n    name: str = field(compare=False)\n\nj = []\nheapq.heappush(j, Job(3, \"x\")); heapq.heappush(j, Job(1, \"y\"))\nprint(heapq.heappop(j).name)   # y"}, "more": "- Prefer tuples for speed and simplicity; use `__lt__` when the order logic is complex.\n- `field(compare=False)` keeps a field out of comparisons.", "see": ["#/topic/heaps"], "check": "assert heapq.heappop(h).name==\"a\"\nassert heapq.heappop(j).name==\"x\""},
    {"id": "pylib-heapq-k-largest", "title": "Find the k-th largest element with a heap", "q": ["kth largest element in an array python", "keep top k with a min heap", "k largest numbers using heap", "find kth largest number", "streaming kth largest"], "tags": "kth largest min heap size k top k stream heappushpop", "a": "Keep a min-heap of size k: the root is the k-th largest seen so far. Push each number, pop when the size exceeds k. The answer is `h[0]` after processing all, in O(n log k) time and O(k) space.", "code": {"py": "import heapq\n\ndef kth_largest(nums, k):\n    h = []\n    for x in nums:\n        heapq.heappush(h, x)\n        if len(h) > k:\n            heapq.heappop(h)\n    return h[0]\n\nprint(kth_largest([3, 2, 1, 5, 6, 4], 2))   # 5\nprint(heapq.nlargest(2, [3, 2, 1, 5, 6, 4])[-1])   # 5, same thing"}, "more": "- Quickselect gives O(n) average but O(n^2) worst case.\n- For k-th smallest use a max-heap (negate values).", "cx": "Time O(n log k), space O(k)", "see": ["#/topic/heaps", "#/problem/215"], "check": "assert kth_largest([3,2,1,5,6,4],2)==5\nassert kth_largest([1],1)==1\nassert kth_largest([2,2,2],3)==2"},
    {"id": "pylib-heapq-merge", "title": "Merge sorted lists with heapq.merge", "q": ["merge two sorted lists python", "merge k sorted lists", "heapq.merge", "combine sorted iterables lazily", "merge sorted arrays"], "tags": "heapq merge sorted lists k way merge lazy iterator", "a": "`heapq.merge(*sorted_iterables)` lazily yields all items in sorted order, in O(N log k) for k inputs. Wrap it in `list()` to materialise. Inputs must already be sorted.", "code": {"py": "import heapq\na, b, c = [1, 4, 7], [2, 5], [0, 9]\nprint(list(heapq.merge(a, b, c)))   # [0, 1, 2, 4, 5, 7, 9]\nprint(list(heapq.merge([\"a\", \"bb\"], [\"ccc\"], key=len)))   # ['a', 'bb', 'ccc']"}, "more": "- For exactly two lists a two-pointer merge is equally good.\n- To merge k linked lists, push `(val, index, node)` onto a heap.", "cx": "O(N log k)", "see": ["#/topic/heaps", "#/problem/23"], "check": "assert list(heapq.merge(a,b,c))==[0,1,2,4,5,7,9]\nassert list(heapq.merge())==[]\nassert list(heapq.merge([5,3],[4,1],reverse=True))==[5,4,3,1]"},
    {"id": "pylib-heapq-decrease-key", "title": "Heap with no decrease-key: lazy deletion", "q": ["heapq decrease key", "update priority in heap python", "remove item from heapq", "dijkstra without decrease key", "priority queue update priority"], "tags": "heapq decrease key update priority remove lazy deletion stale entries dijkstra", "a": "heapq cannot update or remove an arbitrary entry. Push a new entry with the better priority and skip stale ones when popping (lazy deletion): compare the popped value to the current best. This is how Dijkstra is written with heapq.", "code": {"py": "import heapq\n\ndef dijkstra(graph, src):\n    dist = {src: 0}\n    h = [(0, src)]\n    while h:\n        d, u = heapq.heappop(h)\n        if d > dist.get(u, float(\"inf\")):\n            continue                      # stale entry, skip\n        for v, w in graph[u]:\n            nd = d + w\n            if nd < dist.get(v, float(\"inf\")):\n                dist[v] = nd\n                heapq.heappush(h, (nd, v))   # \"decrease key\" = push again\n    return dist\n\ng = {\"a\": [(\"b\", 4), (\"c\", 1)], \"c\": [(\"b\", 2)], \"b\": []}\nprint(dijkstra(g, \"a\"))   # {'a': 0, 'c': 1, 'b': 3}"}, "more": "- The heap may hold up to E entries, so total time is O((V + E) log V) (log E = O(log V)).\n- For removals, mark ids in a `removed` set and skip them on pop.", "cx": "O((V+E) log V)", "see": ["#/topic/shortest-paths", "#/topic/heaps"], "check": "assert dijkstra(g,\"a\")=={\"a\":0,\"b\":3,\"c\":1}\nassert dijkstra({\"x\":[]},\"x\")=={\"x\":0}"},
    {"id": "pylib-bisect-left-right", "title": "bisect_left vs bisect_right", "q": ["python binary search library", "bisect_left vs bisect_right", "how to use bisect", "bisect module example", "find insertion point in sorted list"], "tags": "bisect bisect_left bisect_right binary search sorted insertion point lower bound upper bound", "a": "`bisect_left(a, x)` returns the first index where x could be inserted keeping order (index of the first element >= x, like lower_bound). `bisect_right(a, x)` returns the index after the last element <= x (first element > x, upper_bound). The list must be sorted.", "code": {"py": "from bisect import bisect_left, bisect_right\na = [1, 2, 2, 2, 5]\nprint(bisect_left(a, 2))    # 1\nprint(bisect_right(a, 2))   # 4\nprint(bisect_left(a, 3))    # 4 (not present, same either side)\nprint(bisect_left(a, 99))   # 5 (end)\n\ndef contains(a, x):\n    i = bisect_left(a, x)\n    return i < len(a) and a[i] == x"}, "more": "- `bisect_right` is also called `bisect`.\n- Both take optional `lo` and `hi` bounds.", "cx": "O(log n)", "see": ["#/topic/binary-search"], "check": "assert bisect_left(a,2)==1 and bisect_right(a,2)==4\nassert contains(a,5) and not contains(a,3) and not contains([],1)"},
    {"id": "pylib-bisect-insort", "title": "Insert into a sorted list (insort)", "q": ["insert into sorted list python", "bisect.insort", "keep a list sorted as you add", "insort left vs right", "sorted insert"], "tags": "insort bisect insert sorted list maintain order", "a": "`bisect.insort(a, x)` inserts x into the already-sorted list, keeping it sorted. Finding the spot is O(log n) but shifting elements makes the insert O(n).", "code": {"py": "from bisect import insort\na = [1, 3, 5]\ninsort(a, 4)\ninsort(a, 0)\nprint(a)    # [0, 1, 3, 4, 5]\ninsort(a, 3)\nprint(a)    # [0, 1, 3, 3, 4, 5]"}, "more": "- `insort_left` puts equal items before existing ones, `insort_right` (default) after; it only matters for objects with keys.\n- Need fast inserts at scale? Use a heap or a balanced tree structure, not a sorted list.", "cx": "O(n) per insert (O(log n) search + shifting)", "see": ["#/topic/binary-search"], "check": "assert a==[0,1,3,3,4,5]\nb=[]; insort(b,1); assert b==[1]"},
    {"id": "pylib-bisect-count-range", "title": "Count elements in a range with bisect", "q": ["count numbers between a and b in sorted list", "how many elements less than x sorted", "bisect count in range", "count of elements <= x in sorted array", "number of items in interval sorted list"], "tags": "bisect count range sorted less than greater than between", "a": "In a sorted list, the count of values in [lo, hi] is `bisect_right(a, hi) - bisect_left(a, lo)`. The count strictly less than x is `bisect_left(a, x)`; the count <= x is `bisect_right(a, x)`.", "code": {"py": "from bisect import bisect_left, bisect_right\na = [1, 2, 2, 4, 7, 9]\ndef count_in(a, lo, hi):\n    return bisect_right(a, hi) - bisect_left(a, lo)\n\nprint(count_in(a, 2, 7))    # 4  (2, 2, 4, 7)\nprint(bisect_left(a, 4))    # 3 elements < 4\nprint(bisect_right(a, 4))   # 4 elements <= 4"}, "cx": "O(log n) per query", "see": ["#/topic/binary-search"], "check": "assert count_in(a,2,7)==4 and count_in(a,10,20)==0 and count_in(a,0,100)==6\nassert count_in([],1,2)==0"},
    {"id": "pylib-bisect-key", "title": "bisect with a key (Python 3.10+) and on a range", "q": ["bisect key parameter", "bisect on list of tuples", "binary search on a custom condition python", "bisect objects by attribute", "bisect on a range of integers"], "tags": "bisect key tuples objects custom predicate binary search range", "a": "Since 3.10, `bisect_left(a, x, key=f)` compares `f(item)` with x (the key is applied to list items, not to x). Before 3.10, bisect on a separate keys list. `bisect_left(range(n), target, key=pred)` binary-searches a monotone function without building a list.", "code": {"py": "from bisect import bisect_left\npeople = [(\"ann\", 20), (\"bob\", 31), (\"cy\", 45)]\ni = bisect_left(people, 30, key=lambda p: p[1])\nprint(people[i])    # ('bob', 31)\n\n# first n where n*n >= 50 (monotone function over a virtual range)\nn = bisect_left(range(100), 50, key=lambda k: k * k)\nprint(n)            # 8\n\nages = [p[1] for p in people]     # pre-3.10 way: separate key list\nprint(bisect_left(ages, 30))      # 1"}, "more": "- The key function runs O(log n) times, not on the whole list.\n- Searching on a derived answer (binary search on the answer) is the most useful pattern.", "cx": "O(log n) key calls", "see": ["#/topic/binary-search"], "check": "assert people[i]==(\"bob\",31) and n==8 and bisect_left(ages,30)==1"},
    {"id": "pylib-itertools-permutations", "title": "All permutations (itertools.permutations)", "q": ["generate all permutations of a list python", "itertools permutations", "permutations of length k", "all orderings of a string", "how many permutations python"], "tags": "itertools permutations orderings generate all arrangements backtracking", "a": "`itertools.permutations(items, r=None)` yields tuples of every ordering of r items (all of them if r is omitted): n!/(n-r)! results. Equal values at different positions are treated as different, so duplicates appear.", "code": {"py": "from itertools import permutations\nprint(list(permutations([1, 2, 3], 2)))\n# [(1, 2), (1, 3), (2, 1), (2, 3), (3, 1), (3, 2)]\nprint([\"\".join(p) for p in permutations(\"abc\")])\n# ['abc', 'acb', 'bac', 'bca', 'cab', 'cba']\nprint(len(list(permutations(\"aab\"))))   # 6, duplicates included\nprint(len(set(permutations(\"aab\"))))    # 3"}, "more": "- Output is in lexicographic order of input positions.\n- It is lazy, so use a loop rather than `list()` for large n.", "cx": "O(n!/(n-r)!) results", "see": ["#/topic/backtracking"], "check": "assert len(list(permutations(range(4))))==24\nassert list(permutations([]))==[()]\nassert len(set(permutations(\"aab\")))==3"},
    {"id": "pylib-itertools-combinations", "title": "Combinations (itertools.combinations)", "q": ["generate all combinations of k elements python", "itertools combinations", "n choose k all subsets of size k", "all subsets of a list python", "combinations with replacement"], "tags": "itertools combinations subsets n choose k powerset with replacement", "a": "`combinations(items, r)` yields every r-length selection, in input order, without repeats: C(n, r) results. `combinations_with_replacement` allows reusing an element. All subsets: chain combinations for r = 0..n.", "code": {"py": "from itertools import combinations, combinations_with_replacement, chain\nprint(list(combinations([1, 2, 3], 2)))   # [(1, 2), (1, 3), (2, 3)]\nprint(list(combinations_with_replacement(\"ab\", 2)))   # [('a','a'),('a','b'),('b','b')]\n\ndef powerset(a):\n    return list(chain.from_iterable(combinations(a, r) for r in range(len(a) + 1)))\n\nprint(powerset([1, 2]))   # [(), (1,), (2,), (1, 2)]"}, "cx": "C(n, r) results", "see": ["#/topic/backtracking"], "check": "assert len(powerset(range(4)))==16\nassert list(combinations([1,2],3))==[]\nassert powerset([])==[()]"},
    {"id": "pylib-itertools-product", "title": "Cartesian product (itertools.product)", "q": ["itertools product", "nested loops as one loop python", "all combinations from several lists", "repeat product binary strings", "cartesian product python"], "tags": "itertools product cartesian nested loops repeat bitstrings", "a": "`product(a, b, ...)` is the same as nested for-loops. `product(x, repeat=k)` repeats one iterable k times, e.g. all binary strings of length k.", "code": {"py": "from itertools import product\nprint(list(product([1, 2], \"ab\")))   # [(1,'a'),(1,'b'),(2,'a'),(2,'b')]\nbits = [\"\".join(p) for p in product(\"01\", repeat=3)]\nprint(bits)    # ['000','001',...,'111']\n# grid neighbours\ndirs = [d for d in product((-1, 0, 1), repeat=2) if d != (0, 0)]\nprint(len(dirs))   # 8"}, "cx": "O(product of lengths)", "see": ["#/topic/backtracking"], "check": "assert len(bits)==8 and bits[0]==\"000\" and bits[-1]==\"111\"\nassert len(dirs)==8\nassert list(product([],[1]))==[]"},
    {"id": "pylib-itertools-accumulate", "title": "Running totals with itertools.accumulate", "q": ["prefix sum python one liner", "accumulate running sum", "itertools accumulate", "running maximum python", "cumulative sum of a list"], "tags": "accumulate prefix sum running total cumulative itertools max initial", "a": "`accumulate(nums)` yields running sums, i.e. a prefix-sum array. Pass a function for other scans (`max` for running max) and `initial=0` (3.8+) to start with a leading 0, which makes range sums `pre[r] - pre[l]`.", "code": {"py": "from itertools import accumulate\nnums = [3, 1, 4, 1, 5]\nprint(list(accumulate(nums)))                 # [3, 4, 8, 9, 14]\nprint(list(accumulate(nums, max)))            # [3, 3, 4, 4, 5]\npre = list(accumulate(nums, initial=0))       # [0, 3, 4, 8, 9, 14]\nprint(pre[4] - pre[1])    # sum of nums[1:4] = 6"}, "cx": "O(n)", "see": ["#/topic/prefix-sums"], "check": "assert pre==[0,3,4,8,9,14] and pre[4]-pre[1]==sum(nums[1:4])\nassert list(accumulate([]))==[]"},
    {"id": "pylib-itertools-groupby", "title": "Group consecutive items with itertools.groupby", "q": ["itertools groupby", "run length encoding python", "group consecutive equal elements", "groupby sorted data", "why does groupby give wrong groups"], "tags": "groupby itertools consecutive runs run length encoding sorted key", "a": "`groupby(iterable, key)` groups only CONSECUTIVE items with the same key, so sort by the key first if you want global groups. Each group is a one-shot iterator: consume it (e.g. `list(g)`) before moving on.", "code": {"py": "from itertools import groupby\n\ndef rle(s):\n    return [(ch, len(list(g))) for ch, g in groupby(s)]\n\nprint(rle(\"aaabccdd\"))   # [('a',3),('b',1),('c',2),('d',2)]\n\nwords = sorted([\"bob\", \"al\", \"cy\", \"dan\"], key=len)\nfor n, g in groupby(words, key=len):\n    print(n, list(g))     # 2 ['al','cy'] / 3 ['bob','dan']"}, "more": "- Unsorted `\"abab\"` gives four groups, not two.\n- For unsorted data use `defaultdict(list)` instead.", "cx": "O(n)", "see": ["#/cheatsheets/python"], "check": "assert rle(\"aaabccdd\")==[(\"a\",3),(\"b\",1),(\"c\",2),(\"d\",2)] and rle(\"\")==[]\nassert len(list(groupby(\"abab\")))==4"},
    {"id": "pylib-itertools-chain", "title": "Flatten and concatenate with itertools.chain", "q": ["flatten a list of lists python", "itertools chain", "concatenate lists without copying", "chain.from_iterable", "join several iterables"], "tags": "chain flatten concatenate lists itertools from_iterable nested", "a": "`chain(a, b, c)` iterates several iterables as one without building a new list. `chain.from_iterable(list_of_lists)` flattens one level. For one-level flattening, a comprehension `[x for row in rows for x in row]` also works.", "code": {"py": "from itertools import chain\nprint(list(chain([1, 2], (3,), \"ab\")))        # [1, 2, 3, 'a', 'b']\nrows = [[1, 2], [3], [4, 5]]\nprint(list(chain.from_iterable(rows)))        # [1, 2, 3, 4, 5]\nprint([x for r in rows for x in r])           # same"}, "more": "- Avoid `sum(rows, [])`: it is O(n^2).\n- Only one level is flattened; deeper nesting needs recursion.", "see": ["#/cheatsheets/python"], "check": "assert list(chain.from_iterable(rows))==[1,2,3,4,5]==[x for r in rows for x in r]\nassert list(chain())==[]"},
    {"id": "pylib-itertools-islice", "title": "Slice an iterator with itertools.islice", "q": ["take first n items from a generator python", "itertools islice", "slice a generator", "get first k elements of an iterator", "skip items in an iterator"], "tags": "islice itertools take first n generator iterator slice lazy", "a": "Generators and iterators cannot be sliced with `[:]`. `islice(it, stop)` or `islice(it, start, stop, step)` takes a lazy slice. It consumes the underlying iterator and does not support negative values.", "code": {"py": "from itertools import islice, count\nfirst5 = list(islice(count(10), 5))\nprint(first5)    # [10, 11, 12, 13, 14]\ngen = (x * x for x in range(100))\nprint(list(islice(gen, 2, 6, 2)))   # [4, 16]"}, "more": "- After `islice`, the original iterator has advanced past the items it consumed.", "see": ["#/cheatsheets/python"], "check": "assert first5==[10,11,12,13,14]\nassert list(islice([1,2,3],0))==[]\nassert list(islice([1,2],10))==[1,2]"},
    {"id": "pylib-itertools-pairwise", "title": "Adjacent pairs: pairwise and zip(a, a[1:])", "q": ["loop over consecutive pairs python", "itertools pairwise", "compare adjacent elements in list", "sliding window of size 2", "differences between consecutive elements"], "tags": "pairwise adjacent consecutive pairs window zip neighbours difference", "a": "`itertools.pairwise(it)` (Python 3.10+) yields `(a0,a1), (a1,a2), ...`. On older versions use `zip(a, a[1:])`. Both give nothing for fewer than two items.", "code": {"py": "from itertools import pairwise\na = [1, 4, 9, 16]\nprint(list(pairwise(a)))                 # [(1,4),(4,9),(9,16)]\nprint([y - x for x, y in pairwise(a)])   # [3, 5, 7]\nprint(list(zip(a, a[1:])) == list(pairwise(a)))   # True\nis_sorted = all(x <= y for x, y in pairwise(a))\nprint(is_sorted)     # True"}, "cx": "O(n)", "see": ["#/cheatsheets/python"], "check": "assert is_sorted and list(pairwise([1]))==[] and list(pairwise([]))==[]"},
    {"id": "pylib-itertools-zip-longest", "title": "zip vs zip_longest", "q": ["zip lists of different length python", "zip_longest", "pad shorter list when zipping", "add two numbers digit by digit lists", "zip strict"], "tags": "zip zip_longest fillvalue uneven length strict itertools", "a": "`zip` stops at the shortest input. `itertools.zip_longest(a, b, fillvalue=0)` runs to the longest and fills gaps. In 3.10+ `zip(a, b, strict=True)` raises `ValueError` if lengths differ.", "code": {"py": "from itertools import zip_longest\na, b = [1, 2, 3], [10, 20]\nprint(list(zip(a, b)))                         # [(1,10),(2,20)]\nprint(list(zip_longest(a, b, fillvalue=0)))    # [(1,10),(2,20),(3,0)]\ntry:\n    list(zip(a, b, strict=True))\nexcept ValueError as e:\n    print(\"lengths differ\")"}, "more": "- Useful for adding numbers stored as digit lists.", "see": ["#/cheatsheets/python"], "check": "assert list(zip_longest(a,b,fillvalue=0))[-1]==(3,0)\nassert list(zip(a,b))==[(1,10),(2,20)]"},
    {"id": "pylib-itertools-cycle", "title": "Repeat forever: itertools.cycle and repeat", "q": ["loop over a list repeatedly python", "itertools cycle", "round robin iteration", "repeat a value n times", "infinite iterator python"], "tags": "cycle repeat count infinite itertools round robin", "a": "`cycle(seq)` loops over a sequence forever, `repeat(x, n)` yields x n times (forever without n), and `count(start, step)` counts up forever. Always bound them with `islice`, `zip` or a break.", "code": {"py": "from itertools import cycle, islice, repeat, count\ncolors = cycle(\"RGB\")\nprint(\"\".join(islice(colors, 7)))   # RGBRGBR\nprint(list(repeat(0, 3)))           # [0, 0, 0]\nprint(list(zip(\"abc\", count(1))))   # [('a',1),('b',2),('c',3)]"}, "more": "- `cycle` stores a copy of the items it has seen.", "see": ["#/cheatsheets/python"], "check": "assert \"\".join(islice(cycle(\"RGB\"),7))==\"RGBRGBR\"\nassert list(repeat(\"x\",0))==[]"},
    {"id": "pylib-itertools-batched", "title": "Split into chunks: itertools.batched (3.12) or manual", "q": ["split list into chunks of size n python", "itertools batched", "chunk a list", "batch iterator python", "divide list into groups of k"], "tags": "batched chunk split batches itertools slices size n", "a": "`itertools.batched(iterable, n)` exists only in Python 3.12+ and yields tuples. On older versions slice in steps of n: `[a[i:i+n] for i in range(0, len(a), n)]`. The last chunk may be shorter.", "code": {"py": "try:\n    from itertools import batched          # Python 3.12+\nexcept ImportError:\n    from itertools import islice\n    def batched(it, n):\n        it = iter(it)\n        while chunk := tuple(islice(it, n)):\n            yield chunk\n\na = list(range(7))\nprint(list(batched(a, 3)))   # [(0,1,2),(3,4,5),(6,)]\nprint([a[i:i + 3] for i in range(0, len(a), 3)])   # lists instead"}, "more": "- `batched` takes any iterable, the slicing version needs a sequence.", "see": ["#/cheatsheets/python"], "check": "assert list(batched(a,3))==[(0,1,2),(3,4,5),(6,)]\nassert list(batched([],3))==[]\nassert list(batched(\"abcd\",2))==[(\"a\",\"b\"),(\"c\",\"d\")]"},
    {"id": "pylib-functools-cache", "title": "Memoize with functools.cache / lru_cache", "q": ["how to memoize a function in python", "lru_cache example", "python memoization decorator", "functools cache", "speed up recursive fibonacci python"], "tags": "lru_cache cache memoization functools decorator dp top-down recursion fibonacci", "a": "Put `@functools.cache` (3.9+, unbounded) or `@lru_cache(maxsize=None)` on a pure recursive function and repeated calls with the same arguments return stored results. Arguments must be hashable (no lists).", "code": {"py": "from functools import cache, lru_cache\n\n@cache\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\n\nprint(fib(80))             # 23416728348467685\nprint(fib.cache_info())    # hits/misses/currsize\n\n@lru_cache(maxsize=128)\ndef grid_paths(r, c):\n    return 1 if r == 0 or c == 0 else grid_paths(r - 1, c) + grid_paths(r, c - 1)\n\nprint(grid_paths(3, 3))    # 20\nfib.cache_clear()"}, "more": "- Lists/dicts as arguments raise `TypeError`; pass tuples.\n- Deep recursion still hits the recursion limit; see `sys.setrecursionlimit`.\n- Call `cache_clear()` between test cases in a judge.", "cx": "Each distinct argument set computed once", "see": ["#/topic/dp-1d", "#/topic/recursion"], "check": "assert fib(80)==23416728348467685 and grid_paths(3,3)==20 and fib(1)==1\nassert grid_paths.cache_info().currsize>0"},
    {"id": "pylib-functools-reduce", "title": "functools.reduce: fold a sequence", "q": ["python reduce", "reduce example", "multiply all elements of a list", "fold a list into a single value", "reduce with initial value"], "tags": "reduce functools fold accumulate product xor gcd", "a": "`reduce(f, items, initial)` applies a two-argument function left to right and returns the single final value. Give an initial value so empty input does not raise.", "code": {"py": "from functools import reduce\nfrom operator import mul, xor\nfrom math import gcd\nnums = [2, 3, 4]\nprint(reduce(mul, nums, 1))      # 24\nprint(reduce(xor, [1, 2, 1]))    # 2  (single number trick)\nprint(reduce(gcd, [12, 18, 30])) # 6\nprint(reduce(mul, [], 1))        # 1"}, "more": "- Prefer `sum`, `max`, `math.prod`, `math.gcd(*nums)` (3.9+) when they exist.\n- Use `itertools.accumulate` when you need every intermediate value.", "see": ["#/cheatsheets/python"], "check": "assert reduce(mul,nums,1)==24 and reduce(xor,[5,7,5])==7 and reduce(gcd,[12,18,30])==6\ntry:\n    reduce(mul,[]); assert False\nexcept TypeError: pass"},
    {"id": "pylib-functools-cmp-to-key", "title": "Custom sort order with cmp_to_key", "q": ["python sort with comparator function", "cmp_to_key", "largest number from list sort", "custom comparison sort python", "python 3 sort with cmp"], "tags": "cmp_to_key comparator sort custom compare functools key largest number", "a": "Python 3 sort takes a `key`, not a comparator. If you only have a compare function that returns negative, zero or positive, wrap it with `functools.cmp_to_key`. Use it for orders that cannot be written as a per-item key.", "code": {"py": "from functools import cmp_to_key\n\ndef cmp(a, b):             # put a before b if a+b makes a bigger number\n    return -1 if a + b > b + a else (1 if a + b < b + a else 0)\n\nnums = [\"3\", \"30\", \"34\", \"5\", \"9\"]\nnums.sort(key=cmp_to_key(cmp))\nprint(\"\".join(nums))       # 9534330"}, "more": "- Try a plain key first (tuple keys, negation); `cmp_to_key` is slower.\n- The classic use is \"Largest Number\".", "see": ["#/topic/sorting", "#/problem/179"], "check": "assert \"\".join(nums)==\"9534330\"\nassert sorted([3,1,2],key=cmp_to_key(lambda a,b:b-a))==[3,2,1]"},
    {"id": "pylib-functools-partial", "title": "functools.partial: pre-fill arguments", "q": ["python partial function", "functools partial example", "fix some arguments of a function", "make a one-argument function from two", "partial vs lambda"], "tags": "partial functools bind arguments curry lambda", "a": "`partial(f, *args, **kwargs)` returns a new callable with some arguments already filled in. It is a cleaner alternative to a throwaway lambda when passing a function to `map`, `sorted` or callbacks.", "code": {"py": "from functools import partial\ndef power(base, exp):\n    return base ** exp\n\nsquare = partial(power, exp=2)\nprint(square(7))                 # 49\nprint(list(map(square, [1, 2, 3])))   # [1, 4, 9]\nto_bin = partial(int, base=2)\nprint(to_bin(\"101\"))             # 5"}, "see": ["#/cheatsheets/python"], "check": "assert square(7)==49 and to_bin(\"101\")==5"},
    {"id": "pylib-functools-total-ordering", "title": "total_ordering and making objects sortable", "q": ["make a class sortable in python", "total_ordering", "define __lt__ __eq__ comparisons", "sort objects by multiple fields", "python compare custom objects"], "tags": "total_ordering sortable __lt__ __eq__ comparison class dataclass order", "a": "Define `__eq__` and one of `__lt__`, `__le__`, `__gt__`, `__ge__`, then decorate with `@total_ordering` to get the rest. Often simpler: `@dataclass(order=True)` or `sorted(objs, key=attrgetter(...))`.", "code": {"py": "from functools import total_ordering\n\n@total_ordering\nclass Version:\n    def __init__(self, major, minor):\n        self.t = (major, minor)\n    def __eq__(self, o):\n        return self.t == o.t\n    def __lt__(self, o):\n        return self.t < o.t\n\nprint(Version(1, 2) <= Version(1, 3))   # True\nprint(max(Version(1, 0), Version(2, 0)).t)   # (2, 0)\nprint(sorted([Version(2, 0), Version(1, 5)])[0].t)   # (1, 5)"}, "more": "- Defining `__eq__` without `__hash__` makes the class unhashable.", "see": ["#/cheatsheets/python"], "check": "assert Version(1,2)<=Version(1,3) and Version(2,0)>Version(1,9) and Version(1,1)>=Version(1,1)"},
    {"id": "pylib-math-gcd-lcm", "title": "gcd and lcm in Python", "q": ["how to find gcd in python", "math.gcd", "lcm of two numbers python", "gcd of a list", "least common multiple"], "tags": "gcd lcm math greatest common divisor least common multiple euclid", "a": "`math.gcd(a, b)` returns the greatest common divisor (it accepts many arguments in 3.9+). `math.lcm(a, b)` (3.9+) returns the least common multiple. Before 3.9: `a // gcd(a, b) * b`.", "code": {"py": "import math\nfrom functools import reduce\nprint(math.gcd(12, 18))        # 6\nprint(math.lcm(4, 6))          # 12\nprint(math.gcd(0, 5))          # 5\nprint(reduce(math.gcd, [12, 18, 30]))   # 6, works on any version\nprint(12 // math.gcd(12, 18) * 18)      # 36 = lcm without math.lcm"}, "more": "- Euclid's algorithm: `while b: a, b = b, a % b`.\n- Divide before multiplying in lcm to keep numbers small (Python ints do not overflow, but other languages do).", "cx": "O(log min(a, b))", "see": ["#/topic/math"], "check": "assert math.gcd(12,18)==6 and math.lcm(4,6)==12 and math.gcd(0,0)==0\nassert reduce(math.gcd,[12,18,30])==6"},
    {"id": "pylib-math-isqrt", "title": "Integer square root (math.isqrt)", "q": ["integer square root python", "math.isqrt vs sqrt", "check if a number is a perfect square", "floor of square root without float error", "sqrt of large number exact"], "tags": "isqrt sqrt square root perfect square integer precision float", "a": "`math.isqrt(n)` returns floor(sqrt(n)) as an exact int (3.8+). Prefer it to `int(n ** 0.5)`, which can be off by one for big values because of float rounding.", "code": {"py": "import math\nprint(math.isqrt(99))     # 9\nprint(math.isqrt(100))    # 10\n\ndef is_square(n):\n    return n >= 0 and math.isqrt(n) ** 2 == n\n\nprint(is_square(144), is_square(145))   # True False\nn = 10**30\nprint(math.isqrt(n * n))  # exactly 10**30"}, "more": "- Negative input raises `ValueError`.\n- Loop `i * i <= n` for trial division, or `range(2, isqrt(n) + 1)`.", "see": ["#/topic/math"], "check": "assert is_square(144) and not is_square(145) and not is_square(-4) and is_square(0)\nassert math.isqrt(n*n)==n\nassert math.isqrt(2)==1"},
    {"id": "pylib-math-comb-perm", "title": "nCr, nPr and factorial in Python", "q": ["how to compute n choose k in python", "math.comb", "math.perm", "factorial python", "binomial coefficient python"], "tags": "comb perm factorial binomial ncr npr math choose combinations count", "a": "`math.comb(n, k)` is n choose k, `math.perm(n, k)` is n!/(n-k)!, and `math.factorial(n)` is n! (all 3.8+, exact big ints). Return 0 when k > n. For answers modulo a prime, take the result `% MOD` or precompute factorials.", "code": {"py": "import math\nprint(math.comb(5, 2))     # 10\nprint(math.perm(5, 2))     # 20\nprint(math.factorial(10))  # 3628800\nprint(math.comb(3, 5))     # 0\nprint(math.factorial(25))  # 15511210043330985984000000, no overflow"}, "more": "- Negative arguments raise `ValueError`.\n- Unique grid paths in an m x n grid is `comb(m + n - 2, m - 1)`.", "see": ["#/topic/math"], "check": "assert math.comb(5,2)==10 and math.perm(5,2)==20 and math.comb(3,5)==0 and math.factorial(0)==1\nassert math.comb(50,25)==126410606437752"},
    {"id": "pylib-math-ceil-floor", "title": "Floor, ceil and integer division", "q": ["ceil division in python", "math.ceil math.floor", "floor division negative numbers", "round up integer division", "python // with negatives"], "tags": "ceil floor integer division round up negative modulo truncate", "a": "`//` floors toward negative infinity (so `-7 // 2 == -4`), and `%` takes the divisor's sign. For ceiling division without floats use `-(-a // b)` or `(a + b - 1) // b` for positive numbers. `int()` truncates toward zero.", "code": {"py": "import math\nprint(7 // 2, -7 // 2)           # 3 -4\nprint(-7 % 3)                    # 2\nprint(math.ceil(7 / 2))          # 4\nprint(-(-7 // 2))                # 4  ceil division, no floats\nprint(int(-3.7), math.floor(-3.7), math.ceil(-3.7))   # -3 -4 -3\nprint(round(2.5), round(3.5))    # 2 4  banker's rounding"}, "more": "- `divmod(a, b)` gives quotient and remainder together.\n- C++ and Java truncate toward zero, so the same expression differs for negatives.", "see": ["#/cheatsheets/python"], "check": "assert -(-7//2)==4 and (7+2-1)//2==4 and -7//2==-4 and -7%3==2\nassert round(2.5)==2 and round(0.5)==0"},
    {"id": "pylib-math-inf", "title": "Infinity in Python (float(\"inf\"))", "q": ["how to represent infinity in python", "float inf", "initialize min with infinity", "math.inf", "largest possible integer python"], "tags": "inf infinity float math.inf initial minimum maximum sentinel nan", "a": "Use `math.inf` (or `float(\"inf\")`) as a sentinel larger than any number, and `-math.inf` for smaller. Python ints never overflow, so there is no \"max int\"; use inf for min/max initialisation and for unreachable distances.", "code": {"py": "import math\nbest = math.inf\nfor x in [5, 2, 8]:\n    best = min(best, x)\nprint(best)                  # 2\nprint(math.inf > 10**100)    # True\nprint(math.inf == math.inf, math.inf - math.inf)   # True nan\ndist = [math.inf] * 3\ndist[0] = 0"}, "more": "- Comparing ints with inf is fine, but `inf` is a float, so results may be floats (`min(inf, 3)` is `3`).\n- `min([], default=inf)` avoids an error on empty input.", "see": ["#/cheatsheets/python"], "check": "assert best==2 and math.inf>10**100 and -math.inf<-10**100\nassert math.isnan(math.inf-math.inf) and min([],default=math.inf)==math.inf"},
    {"id": "pylib-math-log", "title": "Logarithms and bit length (log2)", "q": ["math.log2 python", "how many bits to represent a number", "log base 2 of n", "height of binary tree from n nodes", "floor of log2 n"], "tags": "log2 log bit_length logarithm floor depth height binary", "a": "`math.log2(n)` gives log base 2 as a float. For the exact floor of log2 on a positive int use `n.bit_length() - 1`. `math.log(x, base)` handles other bases but can show float noise.", "code": {"py": "import math\nprint(math.log2(8))            # 3.0\nprint(math.log(1000, 10))      # 2.9999999999999996  float noise!\nprint((37).bit_length() - 1)   # 5 = floor(log2(37))\nprint((255).bit_length())      # 8 bits needed\nprint(math.log10(1000))        # 3.0 prefer log10 for base 10"}, "more": "- Iterating halving `while n > 1: n //= 2` also gives floor(log2 n).", "see": ["#/topic/math", "#/topic/bits"], "check": "assert (37).bit_length()-1==5 and (1).bit_length()==1 and (0).bit_length()==0\nassert math.log2(1024)==10.0\nassert (2**60).bit_length()-1==60"},
    {"id": "pylib-math-isclose", "title": "Compare floats safely (isclose)", "q": ["why is 0.1 + 0.2 not 0.3 in python", "compare floating point numbers", "math.isclose", "float equality python", "floating point precision"], "tags": "float isclose equality precision 0.1+0.2 epsilon tolerance decimal", "a": "Floats are binary approximations, so `0.1 + 0.2 == 0.3` is False. Compare with `math.isclose(a, b)` (relative tolerance 1e-9) or add `abs_tol` when comparing against 0. For exact money-style decimals use integers (cents) or `decimal.Decimal`/`fractions.Fraction`.", "code": {"py": "import math\nfrom fractions import Fraction\nprint(0.1 + 0.2 == 0.3)               # False\nprint(math.isclose(0.1 + 0.2, 0.3))   # True\nprint(math.isclose(1e-12, 0.0, abs_tol=1e-9))   # True (needs abs_tol near 0)\nprint(Fraction(1, 10) + Fraction(2, 10) == Fraction(3, 10))   # True"}, "more": "- In interviews prefer integer arithmetic (compare `a*d == b*c` instead of dividing).", "see": ["#/cheatsheets/python"], "check": "assert 0.1+0.2!=0.3 and math.isclose(0.1+0.2,0.3) and not math.isclose(1e-12,0.0)"},
    {"id": "pylib-bit-ops", "title": "Bitwise operators in Python", "q": ["bitwise operators python", "python and or xor shift", "what does ^ do in python", "left shift right shift python", "bitwise not python"], "tags": "bitwise and or xor shift not operators & | ^ << >> ~ binary", "a": "`&` and, `|` or, `^` xor, `~x` not (equals `-x - 1`), `x << k` multiplies by 2^k, `x >> k` floors division by 2^k. Python ints have unlimited width, so `~` gives a negative number; mask with `& 0xFF...` for a fixed width.", "code": {"py": "a, b = 0b1100, 0b1010\nprint(bin(a & b))    # 0b1000\nprint(bin(a | b))    # 0b1110\nprint(bin(a ^ b))    # 0b110\nprint(~5)            # -6\nprint(1 << 4, 100 >> 2)      # 16 25\nprint((~5) & 0xFF)           # 250, as an 8-bit value\nprint(bin(5)[2:].zfill(8))   # 00000101"}, "more": "- Unlike C, Python bitwise operators bind tighter than comparisons, so `x & 1 == 0` means `(x & 1) == 0`; parentheses still help readers.\n- `>>` on negatives is arithmetic (sign-extending).", "see": ["#/topic/bits"], "check": "assert a&b==8 and a|b==14 and a^b==6 and ~5==-6 and (~5)&0xFF==250 and -8>>1==-4\nassert 7^7==0 and 7^0==7"},
    {"id": "pylib-bit-count", "title": "Count set bits (popcount)", "q": ["how to count the number of 1 bits in python", "int.bit_count", "popcount python", "count set bits in a number", "hamming weight"], "tags": "popcount bit_count set bits ones hamming weight bin count kernighan", "a": "`n.bit_count()` (Python 3.10+) returns the number of 1 bits. On older versions use `bin(n).count(\"1\")`, or Kernighan's loop `n &= n - 1`, which runs once per set bit.", "code": {"py": "n = 0b101101\nprint(n.bit_count() if hasattr(n, \"bit_count\") else bin(n).count(\"1\"))   # 4\n\ndef popcount(n):\n    c = 0\n    while n:\n        n &= n - 1      # clears the lowest set bit\n        c += 1\n    return c\n\nprint(popcount(n))   # 4\nprint(bin(n).count(\"1\"))   # 4"}, "cx": "Kernighan: O(number of set bits)", "see": ["#/topic/bits"], "check": "assert popcount(0)==0 and popcount(255)==8 and popcount(n)==bin(n).count(\"1\")==4"},
    {"id": "pylib-bit-set-clear", "title": "Check, set, clear and toggle a bit", "q": ["how to set a bit in python", "check if i-th bit is set", "clear a bit", "toggle bit with xor", "bit manipulation basics"], "tags": "bit manipulation set clear toggle check ith bit mask flag bitmask", "a": "With bit index i (0 = least significant): check `(x >> i) & 1`, set `x | (1 << i)`, clear `x & ~(1 << i)`, toggle `x ^ (1 << i)`.", "code": {"py": "def get(x, i):    return (x >> i) & 1\ndef setb(x, i):   return x | (1 << i)\ndef clear(x, i):  return x & ~(1 << i)\ndef toggle(x, i): return x ^ (1 << i)\n\nx = 0b1010\nprint(get(x, 1), get(x, 0))      # 1 0\nprint(bin(setb(x, 0)))           # 0b1011\nprint(bin(clear(x, 3)))          # 0b10\nprint(bin(toggle(x, 2)))         # 0b1110"}, "more": "- These are the building blocks for bitmask subsets: bit i set means item i is chosen.", "cx": "O(1)", "see": ["#/topic/bits", "#/topic/bitmask-dp"], "check": "assert get(x,1)==1 and get(x,0)==0 and setb(x,0)==11 and clear(x,3)==2 and toggle(toggle(x,2),2)==x\nassert clear(0,5)==0"},
    {"id": "pylib-bit-power-of-two", "title": "Check if a number is a power of two", "q": ["is power of two python", "check power of 2 bit trick", "n & (n-1)", "power of two one liner", "is n a power of two"], "tags": "power of two n&(n-1) bit trick single bit", "a": "A positive n is a power of two exactly when it has a single set bit: `n > 0 and n & (n - 1) == 0`. The `n > 0` guard matters because 0 and negatives must be rejected.", "code": {"py": "def is_pow2(n):\n    return n > 0 and n & (n - 1) == 0\n\nprint([n for n in range(1, 20) if is_pow2(n)])   # [1, 2, 4, 8, 16]\nprint(is_pow2(0), is_pow2(-8))                   # False False"}, "more": "- `n & (n - 1)` clears the lowest set bit; zero left means there was only one.\n- Also `n.bit_count() == 1`.", "cx": "O(1)", "see": ["#/topic/bits", "#/problem/231"], "check": "assert is_pow2(1) and is_pow2(1024) and not is_pow2(0) and not is_pow2(-8) and not is_pow2(6)"},
    {"id": "pylib-bit-lowest-set", "title": "Lowest set bit and iterating bits", "q": ["get the lowest set bit python", "x & -x", "isolate rightmost 1 bit", "loop over set bits of a mask", "index of lowest set bit"], "tags": "lowbit lowest set bit x&-x isolate rightmost fenwick iterate mask", "a": "`x & -x` isolates the lowest set bit as a value (two's complement trick); its index is `(x & -x).bit_length() - 1`. To loop over set bits: take `low = x & -x`, process it, then `x ^= low`.", "code": {"py": "x = 0b101000\nlow = x & -x\nprint(low, low.bit_length() - 1)   # 8 3\n\ndef set_bits(mask):\n    out = []\n    while mask:\n        low = mask & -mask\n        out.append(low.bit_length() - 1)\n        mask ^= low\n    return out\n\nprint(set_bits(0b101001))   # [0, 3, 5]"}, "more": "- `lowbit` is the core of the Fenwick tree.\n- For x = 0, `x & -x` is 0, so guard the index computation.", "see": ["#/topic/bits", "#/topic/fenwick"], "check": "assert set_bits(0b101001)==[0,3,5] and set_bits(0)==[] and 0&-0==0\nassert 12&-12==4"},
    {"id": "pylib-random-basics", "title": "Random numbers: randint, choice, shuffle, sample", "q": ["how to shuffle a list in python", "random.randint inclusive", "pick a random element from a list", "random sample without replacement", "generate random number between a and b"], "tags": "random randint shuffle sample choice randrange seed", "a": "`random.randint(a, b)` includes both ends; `randrange(a, b)` excludes b. `choice(seq)` picks one, `sample(seq, k)` picks k distinct items, `shuffle(lst)` shuffles in place (returns None). Call `random.seed(n)` for reproducible runs.", "code": {"py": "import random\nrandom.seed(1)\nprint(random.randint(1, 6) in range(1, 7))   # True\na = [1, 2, 3, 4, 5]\nrandom.shuffle(a)            # in place, returns None\nprint(sorted(a))             # [1, 2, 3, 4, 5]\nprint(len(random.sample(range(100), 5)))   # 5 distinct values\nprint(random.choice(\"abc\") in \"abc\")       # True"}, "more": "- `random.shuffle` is Fisher-Yates, O(n).\n- `sample(range(n), k)` works without building the list.\n- `random.random()` is in [0, 1).", "see": ["#/cheatsheets/python"], "check": "assert sorted(a)==[1,2,3,4,5] and len(set(random.sample(range(100),5)))==5\nassert all(1<=random.randint(1,3)<=3 for _ in range(50))\nassert random.shuffle([1]) is None"},
    {"id": "pylib-copy-deepcopy", "title": "Copy a list: shallow vs deep copy", "q": ["how to copy a list in python", "copy vs deepcopy", "shallow copy nested list problem", "clone a 2d list python", "a = b changes both lists"], "tags": "copy deepcopy shallow list slice alias reference nested clone", "a": "`b = a` just makes another name for the same list. `a[:]`, `a.copy()` or `list(a)` make a shallow copy (new outer list, same inner objects). For nested lists use `copy.deepcopy(a)`, or `[row[:] for row in grid]` for a 2D grid.", "code": {"py": "import copy\na = [[1, 2], [3]]\nalias = a\nshallow = a[:]\ndeep = copy.deepcopy(a)\na[0].append(99)\nprint(alias[0], shallow[0], deep[0])   # [1,2,99] [1,2,99] [1, 2]\ngrid2 = [row[:] for row in a]          # fast 2D copy\na.append([7])\nprint(len(shallow), len(alias))        # 2 3"}, "more": "- Copying is O(n) (deepcopy is O(total elements) and slower).\n- Backtracking: append `path[:]` or `list(path)` to results, never `path` itself.", "cx": "O(n) for shallow copy", "see": ["#/topic/backtracking"], "check": "assert deep[0]==[1,2] and shallow[0] is a[0] and alias is a and len(shallow)==2 and grid2[0]==[1,2,99] and grid2[0] is not a[0]"},
    {"id": "pylib-sys-recursion-limit", "title": "Raise the recursion limit (sys.setrecursionlimit)", "q": ["recursionerror maximum recursion depth exceeded python", "sys.setrecursionlimit", "python recursion limit 1000", "deep recursion dfs python", "how to avoid recursion error"], "tags": "recursion limit setrecursionlimit recursionerror stack overflow depth dfs iterative", "a": "CPython allows about 1000 nested calls by default. `sys.setrecursionlimit(n)` raises it, but very deep recursion can still crash the interpreter, so for deep DFS (path of 100k nodes) convert to an explicit stack.", "code": {"py": "import sys\nprint(sys.getrecursionlimit())      # 1000 by default\nsys.setrecursionlimit(5000)\n\ndef depth(n):\n    return 0 if n == 0 else 1 + depth(n - 1)\n\nprint(depth(3000))    # 3000 (would fail at the default limit)\n\ndef depth_iter(n):    # loop instead of recursion, no limit\n    d = 0\n    while n:\n        n -= 1; d += 1\n    return d"}, "more": "- The limit counts Python frames, and each uses memory; big values risk a segfault.\n- Interviews: mention converting recursion to an iterative stack.", "see": ["#/topic/recursion"], "check": "assert depth(3000)==3000 and depth_iter(10**6)==10**6"},
    {"id": "pylib-sys-stdin", "title": "Fast input in Python (sys.stdin)", "q": ["fast input python competitive programming", "sys.stdin.readline", "read all input at once python", "read ints from a line", "input() too slow"], "tags": "sys stdin readline read input fast competitive programming split map int", "a": "`input()` is slow for large inputs. Use `sys.stdin.readline` (keeps the trailing newline) or read everything once with `sys.stdin.read().split()` and parse the tokens.", "code": {"py": "import sys, io\nsys.stdin = io.StringIO(\"3\\n10 20 30\\n\")   # simulate stdin for this demo\ninput = sys.stdin.readline                  # common alias\nn = int(input())\nnums = list(map(int, input().split()))\nprint(n, sum(nums))     # 3 60\n\nsys.stdin = io.StringIO(\"1 2 3\\n4 5\\n\")\ndata = sys.stdin.read().split()\nprint(list(map(int, data)))   # [1, 2, 3, 4, 5]"}, "more": "- `readline()` returns an empty string at EOF.\n- Strip the newline with `.strip()` or `.rstrip()` for string lines.", "see": ["#/cheatsheets/python"], "check": "assert n==3 and nums==[10,20,30] and data==[\"1\",\"2\",\"3\",\"4\",\"5\"]"},
    {"id": "pylib-sys-maxsize", "title": "Largest and smallest integer in Python", "q": ["max int in python", "sys.maxsize", "python integer overflow", "initialize min to a big number", "what is int max in python"], "tags": "maxsize integer overflow big int infinity sys max int", "a": "Python ints are arbitrary precision, so they never overflow. `sys.maxsize` (2**63 - 1 on 64-bit) is just the largest container index, handy as a sentinel; `float(\"inf\")` is the safer sentinel. Simulate 32-bit overflow yourself by masking.", "code": {"py": "import sys\nprint(sys.maxsize)            # 9223372036854775807 on 64-bit\nprint(2**100 + 1)             # fine, no overflow\nINT_MAX = 2**31 - 1\nprint(INT_MAX + 1 > INT_MAX)  # True in Python; would overflow in Java/C++\n\ndef to_int32(x):\n    x &= 0xFFFFFFFF\n    return x - (1 << 32) if x >> 31 else x\nprint(to_int32(INT_MAX + 1))  # -2147483648"}, "more": "- Java/C++ `int` overflow wraps; in Python you must emulate it if a problem asks.", "see": ["#/cheatsheets/python"], "check": "assert to_int32(2**31)==-2**31 and to_int32(5)==5 and to_int32(-1)==-1 and sys.maxsize>2**31"},
    {"id": "pylib-typing-hints", "title": "Type hints for lists, dicts and optionals", "q": ["python type hints for leetcode", "List[int] vs list[int]", "Optional[int] python", "type hint for dict of lists", "what does -> None mean python"], "tags": "typing type hints List Optional Dict annotations list[int] leetcode TreeNode", "a": "Hints are optional documentation; Python does not enforce them. Since 3.9 use built-in generics: `list[int]`, `dict[str, list[int]]`, `tuple[int, int]`. Use `Optional[X]` or `X | None` (3.10+) for a value that can be None. LeetCode imports `List` from `typing`.", "code": {"py": "from typing import List, Optional\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val, self.next = val, next\n\ndef two_sum(nums: List[int], target: int) -> List[int]:\n    seen: dict[int, int] = {}\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            return [seen[target - x], i]\n        seen[x] = i\n    return []\n\ndef last(head: Optional[ListNode]) -> Optional[ListNode]:\n    while head and head.next:\n        head = head.next\n    return head"}, "more": "- Forgetting `from typing import List` is a common error when running LeetCode code locally.\n- Hints do not change runtime behaviour or speed.", "see": ["#/cheatsheets/python"], "check": "assert two_sum([2,7,11],9)==[0,1] and two_sum([1],5)==[]\nassert last(None) is None\nn=ListNode(1,ListNode(2)); assert last(n).val==2"},
    {"id": "pylib-generators-yield", "title": "Generators and yield", "q": ["what is yield in python", "python generator example", "generator vs list", "lazy evaluation python", "generator expression"], "tags": "generator yield lazy iterator generator expression memory next", "a": "A function containing `yield` returns a generator: it produces values lazily, one per `next()`, pausing between them. Use it to avoid building a big list. A generator expression `(x*x for x in it)` is the one-line form, and it can be consumed only once.", "code": {"py": "def evens(limit):\n    for n in range(0, limit, 2):\n        yield n\n\ng = evens(7)\nprint(next(g), next(g))     # 0 2\nprint(list(g))              # [4, 6]  (continues where it left off)\nprint(list(g))              # []      (exhausted)\n\ntotal = sum(x * x for x in range(1000))   # no intermediate list\nprint(total)                # 332833500\n\ndef inorder(node):          # recursive generator; node = (left, val, right)\n    if node:\n        yield from inorder(node[0])\n        yield node[1]\n        yield from inorder(node[2])\nprint(list(inorder(((None, 1, None), 2, (None, 3, None)))))   # [1, 2, 3]"}, "more": "- `yield from` delegates to another iterable.\n- A generator is an iterator: `iter(g) is g`.", "cx": "O(1) memory for the generator itself", "see": ["#/cheatsheets/python"], "check": "assert total==332833500 and list(inorder(((None,1,None),2,None)))==[1,2]\nassert list(evens(0))==[]"},
    {"id": "pylib-iterators-protocol", "title": "Make a class iterable (__iter__ / __next__)", "q": ["how to make an object iterable python", "__iter__ and __next__", "iterator vs iterable", "custom iterator class", "StopIteration"], "tags": "iterator iterable __iter__ __next__ StopIteration protocol for loop class", "a": "An iterable has `__iter__` returning an iterator; an iterator has `__next__` that returns the next value and raises `StopIteration` at the end. The easiest way is `__iter__` written as a generator. `iter(x)` and `next(it, default)` are the built-in helpers.", "code": {"py": "class Countdown:\n    def __init__(self, n):\n        self.n = n\n    def __iter__(self):\n        n = self.n\n        while n > 0:\n            yield n\n            n -= 1\n\nprint(list(Countdown(3)))      # [3, 2, 1]\nprint(list(Countdown(3)))      # again works: new generator each time\nit = iter([10, 20])\nprint(next(it), next(it), next(it, \"done\"))   # 10 20 done"}, "more": "- Lists are iterables; `iter(list)` is an iterator and is exhausted after one pass.\n- This is how BST iterators are built (stack + generator).", "see": ["#/cheatsheets/python"], "check": "assert list(Countdown(3))==[3,2,1] and list(Countdown(0))==[]\nassert next(iter([]),None) is None"},
    {"id": "pylib-enumerate-tricks", "title": "enumerate tricks", "q": ["loop with index python", "enumerate start at 1", "get index and value in for loop", "enumerate dictionary", "find index of max value"], "tags": "enumerate index value loop start zip range len max argmax", "a": "`for i, x in enumerate(items, start=1)` gives index and value together; do not write `range(len(items))` unless you need it. The index of the max is `max(range(len(a)), key=a.__getitem__)` or `a.index(max(a))`.", "code": {"py": "a = [4, 9, 2]\nfor i, x in enumerate(a, start=1):\n    print(i, x)                  # 1 4 / 2 9 / 3 2\nprint(max(range(len(a)), key=a.__getitem__))   # 1\npos = {x: i for i, x in enumerate(a)}           # value -> index\nprint(pos[2])                    # 2\nprint(max(enumerate(a), key=lambda p: p[1]))    # (1, 9)"}, "see": ["#/cheatsheets/python"], "check": "assert pos[9]==1 and a.index(max(a))==1 and list(enumerate(\"ab\",1))==[(1,\"a\"),(2,\"b\")]"},
    {"id": "pylib-zip-transpose", "title": "Transpose a matrix with zip(*matrix)", "q": ["transpose a matrix in python", "zip(*matrix)", "rotate matrix 90 degrees python", "columns of a 2d list", "what does zip star do"], "tags": "zip transpose matrix star unpack columns rotate 90 degrees 2d", "a": "`list(zip(*matrix))` transposes: `*` unpacks the rows as separate arguments and zip pairs up their i-th elements. Rotate 90 degrees clockwise with `[list(r) for r in zip(*matrix[::-1])]`. Rows must have equal lengths or the extras are dropped.", "code": {"py": "m = [[1, 2, 3], [4, 5, 6]]\nprint(list(zip(*m)))                      # [(1,4),(2,5),(3,6)]\nt = [list(col) for col in zip(*m)]\nprint(t)                                  # [[1,4],[2,5],[3,6]]\nrot = [list(r) for r in zip(*m[::-1])]    # clockwise\nprint(rot)                                # [[4,1],[5,2],[6,3]]\nprint([sum(c) for c in zip(*m)])          # column sums [5, 7, 9]"}, "more": "- Empty matrix gives an empty result; guard if you index `t[0]` afterwards.\n- Counterclockwise: `list(zip(*m))[::-1]`.", "cx": "O(rows * cols)", "see": ["#/topic/matrix"], "check": "assert t==[[1,4],[2,5],[3,6]] and rot==[[4,1],[5,2],[6,3]]\nassert list(zip(*[]))==[]"},
    {"id": "pylib-sort-itemgetter", "title": "Sort by field with itemgetter / attrgetter", "q": ["sort list of tuples by second element", "sort list of dicts by key python", "operator.itemgetter", "attrgetter sort objects", "sort by multiple keys"], "tags": "sorted itemgetter attrgetter key sort tuples dicts multiple keys operator", "a": "`sorted(rows, key=itemgetter(1))` sorts tuples/lists/dicts by that index or key; `attrgetter(\"age\")` does it for objects. Multiple fields: `itemgetter(1, 0)`, or a lambda returning a tuple; negate numbers for descending parts.", "code": {"py": "from operator import itemgetter, attrgetter\nrows = [(\"bob\", 25), (\"ann\", 25), (\"cy\", 20)]\nprint(sorted(rows, key=itemgetter(1)))      # by age, stable\nprint(sorted(rows, key=itemgetter(1, 0)))   # by age then name\nprint(sorted(rows, key=lambda r: (-r[1], r[0])))   # age desc, name asc\n\nclass P:\n    def __init__(self, n, a): self.n, self.a = n, a\nps = [P(\"x\", 3), P(\"y\", 1)]\nprint([p.n for p in sorted(ps, key=attrgetter(\"a\"))])   # ['y','x']\nprint(sorted([{\"k\": 2}, {\"k\": 1}], key=itemgetter(\"k\")))"}, "more": "- Python sort is stable: equal keys keep their original order, so sort by the secondary key first when chaining separate sorts.", "cx": "O(n log n)", "see": ["#/topic/sorting"], "check": "assert sorted(rows,key=itemgetter(1,0))==[(\"cy\",20),(\"ann\",25),(\"bob\",25)]\nassert sorted(rows,key=lambda r:(-r[1],r[0]))[0]==(\"ann\",25)\nassert [p.n for p in sorted(ps,key=attrgetter(\"a\"))]==[\"y\",\"x\"]"},
    {"id": "pylib-string-basics", "title": "Common string operations in Python", "q": ["python string methods cheat sheet", "strings are immutable python", "split join strip python", "how to build a string efficiently", "reverse a string python"], "tags": "string str split join strip reverse slicing immutable replace find startswith", "a": "Strings are immutable: every change creates a new string. Build pieces in a list and `\"\".join(parts)` at the end (repeated `+=` in a loop can be O(n^2)). Reverse with `s[::-1]`; `split()` splits on whitespace; `strip()` trims.", "code": {"py": "s = \"  Hello, World  \"\nprint(s.strip().lower())          # hello, world\nprint(\"a,b,c\".split(\",\"))         # ['a','b','c']\nprint(\"-\".join([\"x\", \"y\", \"z\"]))  # x-y-z\nprint(\"hello\"[::-1])              # olleh\nprint(\"hello\".find(\"l\"), \"hello\".find(\"z\"))   # 2 -1\nprint(\"abc\".startswith(\"ab\"), \"a b\".split())  # True ['a', 'b']\nchars = list(\"abc\"); chars[0] = \"z\"\nprint(\"\".join(chars))             # zbc  (mutate via a list)"}, "more": "- `ord(\"a\")` is 97 and `chr(97)` is \"a\"; `ord(c) - ord(\"a\")` gives a 0-25 index.\n- Slices copy, so `s[1:]` in a loop is O(n) each time.", "see": ["#/cheatsheets/python"], "check": "assert \"\".join(chars)==\"zbc\" and \"hello\"[::-1]==\"olleh\" and \"\".join([])==\"\"\ntry:\n    s[0]=\"x\"; assert False\nexcept TypeError: pass"},
    {"id": "pylib-bytes-bytearray", "title": "bytes vs str and bytearray", "q": ["bytes vs string python", "encode decode python", "bytearray mutable", "convert string to bytes", "utf-8 length of a string"], "tags": "bytes bytearray encode decode utf-8 string ascii mutable", "a": "`str` is text (Unicode); `bytes` is raw immutable bytes. `s.encode()` gives UTF-8 bytes and `b.decode()` converts back. `bytearray` is a mutable bytes, useful as a compact buffer of small ints.", "code": {"py": "s = \"h\\u00e9llo\"\nb = s.encode(\"utf-8\")\nprint(len(s), len(b))        # 5 6 (the accented e takes 2 bytes)\nprint(b.decode() == s)       # True\nba = bytearray(b\"abc\")\nba[0] = 65\nprint(ba)                    # bytearray(b'Abc')\nprint(list(b\"AB\"))           # [65, 66]\nflags = bytearray(5)         # five zero bytes, compact visited array\nflags[3] = 1"}, "more": "- Indexing `bytes` gives ints, not 1-char strings.", "see": ["#/cheatsheets/python"], "check": "assert len(b)==6 and ba==bytearray(b\"Abc\") and list(flags)==[0,0,0,1,0]"},
    {"id": "pylib-timing-code", "title": "Measure running time (perf_counter, timeit)", "q": ["how to time a function in python", "timeit example", "time.perf_counter", "measure execution time", "benchmark two approaches python"], "tags": "timeit perf_counter time measure benchmark execution speed profile", "a": "Use `time.perf_counter()` before and after the code (subtract), or `timeit.timeit(stmt, number=n)` to repeat a snippet and reduce noise. Avoid `time.time()` for short intervals because it has lower resolution and can jump.", "code": {"py": "import time, timeit\nt = time.perf_counter()\nsum(range(10**6))\nprint(f\"{time.perf_counter() - t:.4f}s\")\n\nt_list = timeit.timeit(\"99999 in a\", \"a = list(range(100000))\", number=200)\nt_set = timeit.timeit(\"99999 in a\", \"a = set(range(100000))\", number=200)\nprint(t_set < t_list)    # True: set membership is O(1)"}, "more": "- Put timed code in a function and measure the median of several runs.\n- `python -m timeit \"stmt\"` works from the shell.", "see": ["#/cheatsheets/python"], "check": "assert t_set < t_list"},
    {"id": "pylib-sizeof-memory", "title": "Check memory size (sys.getsizeof)", "q": ["how much memory does a list use python", "sys.getsizeof", "size of an object in python", "memory usage of data structure", "getsizeof nested list"], "tags": "getsizeof memory size bytes object list shallow tracemalloc", "a": "`sys.getsizeof(obj)` returns the object's own size in bytes, NOT counting the objects it refers to (a shallow size). For real totals sum recursively or use `tracemalloc`. Containers over-allocate, so size jumps in steps.", "code": {"py": "import sys\nprint(sys.getsizeof([]))               # 56 on 64-bit CPython 3.11\nprint(sys.getsizeof(list(range(100))) > sys.getsizeof([]))   # True\nnested = [[0] * 1000 for _ in range(10)]\nprint(sys.getsizeof(nested) < 1000)    # True: counts only 10 pointers\nprint(sys.getsizeof(range(10**9)))     # 48, range stores only start/stop/step"}, "more": "- Exact byte counts differ by version and platform; do not hard-code them.\n- 10**6 small ints in a list cost far more than 10**6 bytes (use `array`, `bytearray` or numpy for compact storage).", "see": ["#/cheatsheets/python"], "check": "assert sys.getsizeof(nested)<1000 and sys.getsizeof(range(10**9))<100 and sys.getsizeof([1,2,3])>sys.getsizeof([])"},
    {"id": "pylib-complexity-list-ops", "title": "Time complexity of Python list operations", "q": ["python list complexity", "list append pop insert big o", "is list in operator O(n)", "list slicing time complexity", "big o of list methods"], "tags": "list complexity big o append pop insert remove index in slice sort cost", "a": "Index, `append` (amortized) and `pop()` from the end are O(1). `insert(i)`, `pop(0)`, `remove`, `index`, `x in list` and `count` are O(n). Slicing is O(k) for k items, `sort` is O(n log n), `a + b` is O(n+m), `len` is O(1).", "code": {"py": "import timeit\nbig = list(range(100_000))\nfast = timeit.timeit(lambda: (big.append(1), big.pop()), number=2000)\nslow = timeit.timeit(lambda: (big.insert(0, 1), big.pop(0)), number=2000)\nprint(slow > fast)    # True: front operations shift everything\n\na = [1, 2, 3]\nprint(3 in a)         # O(n) scan\nprint(a[1:])          # O(k) copy"}, "more": "- `list.append` is amortized O(1): occasional resizes are spread over many appends.\n- `del a[i]` is O(n) except at the end.", "cx": "See list above", "see": ["#/cheatsheets/big-o-algorithms", "#/topic/big-o"], "check": "assert slow>fast"},
    {"id": "pylib-complexity-dict-set", "title": "Time complexity of dict, set, str and heap ops", "q": ["python dict lookup complexity", "set membership big o", "is dict O(1)", "string concatenation complexity python", "complexity of python built-in operations"], "tags": "dict set complexity big o hash lookup membership string concat heap deque", "a": "dict and set insert, lookup and delete are O(1) on average and O(n) worst case (heavy hash collisions). `in` on a set is O(1) average but on a list O(n). deque ends O(1); heappush/heappop O(log n); `sorted` O(n log n); `\"\".join` is O(total length); `min`/`max`/`sum` are O(n).", "code": {"py": "s = {1, 2, 3}\nd = {\"a\": 1}\nprint(2 in s, \"a\" in d)        # O(1) average each\n\n# turn repeated list lookups into a set lookup\nallowed = set(range(0, 10**5, 7))\nqueries = range(1000)\nprint(sum(1 for q in queries if q in allowed))   # 143\n\nparts = [str(i) for i in range(5)]\nprint(\"\".join(parts))    # 01234  O(total), not repeated +="}, "more": "- Set union is O(n+m); intersection is O(min(n,m)) on average.\n- Keys must be hashable: ints, strings, tuples of hashables, frozenset; not lists.", "see": ["#/cheatsheets/big-o-algorithms", "#/topic/hashing-internals"], "check": "assert sum(1 for q in queries if q in allowed)==143 and \"\".join(parts)==\"01234\""},
    {"id": "pylib-gotcha-mutable-default", "title": "Mutable default argument bug", "q": ["python function default list keeps growing", "mutable default argument", "def f(x, lst=[]) bug", "why does my default list persist between calls", "default argument evaluated once"], "tags": "mutable default argument gotcha list dict bug none sentinel function", "a": "Default values are evaluated ONCE when the function is defined, so a default `[]` or `{}` is shared across all calls. Use `None` as the default and create the list inside.", "code": {"py": "def bad(x, acc=[]):\n    acc.append(x)\n    return acc\n\nprint(bad(1), bad(2))   # [1, 2] [1, 2]  same list!\n\ndef good(x, acc=None):\n    if acc is None:\n        acc = []\n    acc.append(x)\n    return acc\n\nprint(good(1), good(2)) # [1] [2]"}, "more": "- Same trap for dicts, sets and objects like `datetime.now()` (frozen at definition time).", "see": ["#/cheatsheets/python"], "check": "assert bad.__defaults__[0]==[1,2]\nassert good(1)==[1] and good(2)==[2]"},
    {"id": "pylib-gotcha-late-binding", "title": "Late-binding closures in loops", "q": ["lambda in loop all return same value python", "closure captures variable not value", "late binding python", "functions created in a for loop", "why does my lambda use the last i"], "tags": "closure lambda loop late binding default argument capture gotcha", "a": "A closure looks up the variable when it is CALLED, not when it was created, so lambdas made in a loop all see the loop variable's final value. Capture the current value with a default argument (`lambda i=i: i`) or `functools.partial`.", "code": {"py": "fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])      # [2, 2, 2]\n\ngs = [lambda i=i: i for i in range(3)]\nprint([g() for g in gs])      # [0, 1, 2]"}, "more": "- Comprehension variables are local to the comprehension, but the lambda still resolves `i` late.", "see": ["#/cheatsheets/python"], "check": "assert [f() for f in fs]==[2,2,2] and [g() for g in gs]==[0,1,2]"},
    {"id": "pylib-gotcha-modify-while-iterating", "title": "Modifying a list while iterating over it", "q": ["remove items from list while looping python", "why does my for loop skip elements", "delete from list during iteration", "dictionary changed size during iteration", "filter a list in place"], "tags": "modify list while iterating remove skip bug comprehension copy filter", "a": "Removing from a list while looping over it shifts the remaining items, so the loop skips elements. Build a new list with a comprehension, loop over a copy (`for x in a[:]`), or iterate backwards. Changing a dict's size during iteration raises `RuntimeError`.", "code": {"py": "nums = [2, 4, 6, 1]\nfor x in nums:\n    if x % 2 == 0:\n        nums.remove(x)\nprint(nums)    # [4, 1]  wrong: 4 was skipped\n\nnums = [2, 4, 6, 1]\nnums = [x for x in nums if x % 2]       # correct\nprint(nums)    # [1]\nd = {\"a\": 1}\ntry:\n    for k in d:\n        d[\"b\"] = 2\nexcept RuntimeError:\n    print(\"dict changed size\")"}, "more": "- To delete dict keys while looping, iterate `list(d)`.\n- `nums[:] = [...]` filters in place, keeping the same list object.", "see": ["#/cheatsheets/python"], "check": "assert nums==[1]\nb=[2,4,6,1]\nfor x in b[:]:\n    if x%2==0: b.remove(x)\nassert b==[1]"},
    {"id": "pylib-gotcha-2d-list", "title": "Creating a 2D list: [[0]*n]*m bug", "q": ["create 2d array python", "matrix of zeros python", "why do all rows change at once", "[[0]*3]*3 problem", "initialize grid in python"], "tags": "matrix 2d list grid initialize zeros aliasing rows bug dp table comprehension", "a": "`[[0] * n] * m` repeats the SAME inner list m times, so changing one row changes all. Build each row separately: `[[0] * n for _ in range(m)]`. (`[0] * n` itself is fine for immutable items.)", "code": {"py": "bad = [[0] * 3] * 2\nbad[0][0] = 7\nprint(bad)     # [[7, 0, 0], [7, 0, 0]]\n\ngrid = [[0] * 3 for _ in range(2)]\ngrid[0][0] = 7\nprint(grid)    # [[7, 0, 0], [0, 0, 0]]\ndp = [[0] * (4 + 1) for _ in range(3 + 1)]   # (rows+1) x (cols+1) table"}, "more": "- Same trap with `[[]] * n` for adjacency lists: use `[[] for _ in range(n)]`.", "see": ["#/topic/matrix", "#/topic/dp-2d"], "check": "assert bad[0] is bad[1] and bad==[[7,0,0],[7,0,0]]\nassert grid==[[7,0,0],[0,0,0]] and len(dp)==4 and len(dp[0])==5"},
    {"id": "pylib-gotcha-is-vs-eq", "title": "== vs is and small integer caching", "q": ["difference between is and == in python", "python is operator with numbers", "integer caching python", "why a is b true for small numbers", "compare to None with is"], "tags": "is equals == identity integer cache small ints none singleton", "a": "`==` compares values; `is` compares object identity. Use `is` only for singletons like `None`. CPython caches small ints (-5 to 256) so `is` may seem to work for them, but it fails for bigger values and is an implementation detail.", "code": {"py": "a, b = int(\"100\"), int(\"100\")\nprint(a == b, a is b)      # True True  (cached small ints)\nx, y = int(\"1000\"), int(\"1000\")\nprint(x == y, x is y)      # True False (separate objects)\n\nl1, l2 = [1], [1]\nprint(l1 == l2, l1 is l2)  # True False\nval = None\nprint(val is None)         # True, the right way"}, "more": "- Never write `if x is 5` (it raises a SyntaxWarning).", "see": ["#/cheatsheets/python"], "check": "assert a==b and x==y and l1==l2 and l1 is not l2 and val is None"},
    {"id": "pylib-gotcha-shallow-nested", "title": "Shallow copy trap: appending path in backtracking", "q": ["list of lists changes unexpectedly", "list.copy only copies top level", "shared reference python list append", "same list in two variables", "append path to result list backtracking bug"], "tags": "shallow copy reference alias nested mutate append result path backtracking bug", "a": "Assignment and shallow copies share inner objects. In backtracking, `res.append(path)` stores a reference that later changes, so append a copy: `res.append(path[:])`. For a dict of lists, `dict.copy()` still shares the lists.", "code": {"py": "res, path = [], []\ndef walk(i):\n    if i == 3:\n        res.append(path[:])      # copy! (not res.append(path))\n        return\n    for x in (0, 1):\n        path.append(x); walk(i + 1); path.pop()\n\nwalk(1)\nprint(res)     # [[0, 0], [0, 1], [1, 0], [1, 1]]\n\nd = {\"a\": [1]}\nd2 = d.copy()\nd2[\"a\"].append(2)\nprint(d[\"a\"])  # [1, 2]  shared!"}, "more": "- If you saw `[[], [], [], []]` as final output, you appended the same list that was emptied by `pop()`.", "see": ["#/topic/backtracking"], "check": "assert res==[[0,0],[0,1],[1,0],[1,1]] and d[\"a\"]==[1,2]"},
    {"id": "pylib-gotcha-inplace-returns-none", "title": "sort() returns None, and other beginner traps", "q": ["python list.sort returns none", "why does sort print none", "a = a.sort() gives None", "python 3 division gives float", "typeerror can only concatenate str"], "tags": "sort returns none division float typeerror concatenate gotcha reverse in place", "a": "In-place methods (`sort`, `reverse`, `append`, `shuffle`) return None, so `a = a.sort()` loses your list; use `sorted(a)`. In Python 3, `/` is true division (float); use `//` for integers. Convert before joining text and numbers: `\"n=\" + str(n)` or an f-string.", "code": {"py": "a = [3, 1, 2]\nprint(a.sort())      # None\nprint(a)             # [1, 2, 3]\nb = sorted([3, 1, 2], reverse=True)\nprint(b)             # [3, 2, 1]\nprint(7 / 2, 7 // 2) # 3.5 3\nn = 5\nprint(f\"n={n}\")      # n=5"}, "more": "- `reversed(a)` returns an iterator; wrap with `list()` or use `a[::-1]`.", "see": ["#/cheatsheets/python"], "check": "assert a==[1,2,3] and b==[3,2,1] and 7/2==3.5 and 4/2==2.0 and f\"n={n}\"==\"n=5\""},
    {"id": "pylib-dict-ops", "title": "Dictionary essentials: get, setdefault, items, sorted by value", "q": ["python dict methods", "dict get with default", "sort a dictionary by value", "loop over dictionary key and value", "merge two dictionaries python"], "tags": "dict get setdefault items sort by value merge update keys values", "a": "Use `d.get(k, default)` to avoid KeyError, `d.setdefault(k, [])` to insert a default, `d.items()` to loop key/value, and `{**a, **b}` or `a | b` (3.9+) to merge. Sort by value with `sorted(d.items(), key=lambda kv: kv[1])`.", "code": {"py": "d = {\"b\": 2, \"a\": 3, \"c\": 1}\nprint(d.get(\"z\", 0))                             # 0\nprint(sorted(d.items(), key=lambda kv: kv[1]))   # [('c',1),('b',2),('a',3)]\nbest = max(d, key=d.get)\nprint(best)                                      # a\nprint({**d, \"z\": 9}[\"z\"], (d | {\"a\": 0})[\"a\"])   # 9 0\nd.setdefault(\"q\", []).append(1)\nfor k, v in d.items():\n    pass\nprint(list(d)[:2])    # insertion order: ['b', 'a']"}, "more": "- Dicts keep insertion order (3.7+).\n- Deleting while looping raises an error; iterate over `list(d)`.", "see": ["#/topic/arrays-hashing"], "check": "assert d.get(\"z\",0)==0 and best==\"a\" and d[\"q\"]==[1] and list(d)[:2]==[\"b\",\"a\"]"},
    {"id": "pylib-set-ops", "title": "Set operations: union, intersection, difference", "q": ["python set operations", "intersection of two lists python", "remove duplicates from a list keep order", "set difference python", "find common elements"], "tags": "set union intersection difference symmetric dedupe duplicates frozenset", "a": "Use `a | b` union, `a & b` intersection, `a - b` difference, `a ^ b` symmetric difference. `set(list)` removes duplicates but loses order; `list(dict.fromkeys(items))` dedupes keeping first-seen order.", "code": {"py": "a, b = {1, 2, 3}, {2, 3, 4}\nprint(a | b, a & b, a - b, a ^ b)   # {1,2,3,4} {2,3} {1} {1,4}\nitems = [3, 1, 3, 2, 1]\nprint(sorted(set(items)))           # [1, 2, 3]\nprint(list(dict.fromkeys(items)))   # [3, 1, 2] order kept\nprint(a <= {1, 2, 3, 9}, a.isdisjoint({7}))   # True True"}, "more": "- Sets need hashable elements: use tuples or frozensets for composite items.", "cx": "union O(n+m), intersection O(min(n,m)) average", "see": ["#/cheatsheets/python"], "check": "assert list(dict.fromkeys(items))==[3,1,2] and a&b=={2,3} and a^b=={1,4}"},
    {"id": "pylib-slicing-tricks", "title": "List slicing cheat sheet", "q": ["python slicing explained", "a[::-1] meaning", "slice every other element", "copy list with slice", "last k elements of a list"], "tags": "slice slicing step negative reverse copy last k start stop", "a": "Slices are `a[start:stop:step]`: start inclusive, stop exclusive, all optional, and out-of-range indexes are clamped (no error). `a[::-1]` reverses, `a[::2]` takes every other item, `a[-k:]` is the last k, `a[:]` copies.", "code": {"py": "a = [0, 1, 2, 3, 4, 5]\nprint(a[1:4])     # [1, 2, 3]\nprint(a[::-1])    # [5, 4, 3, 2, 1, 0]\nprint(a[::2])     # [0, 2, 4]\nprint(a[-2:])     # [4, 5]\nprint(a[:-1])     # [0, 1, 2, 3, 4]\nprint(a[10:20])   # []  no IndexError\na[1:3] = [9]      # slice assignment can resize\nprint(a)          # [0, 9, 3, 4, 5]"}, "more": "- Slicing copies, costing O(k).\n- `a[-k:]` with k = 0 returns the whole list, not an empty one.", "cx": "O(k) per slice", "see": ["#/cheatsheets/python"], "check": "assert a==[0,9,3,4,5] and [1,2][5:]==[] and [1,2,3][-0:]==[1,2,3]"},
    {"id": "pylib-comprehensions", "title": "List, set and dict comprehensions", "q": ["python list comprehension with if", "dict comprehension", "nested list comprehension", "flatten with comprehension", "comprehension vs for loop"], "tags": "comprehension list dict set generator filter map if else nested", "a": "`[expr for x in it if cond]` builds a list; `{x for ...}` a set; `{k: v for ...}` a dict. A ternary goes in the expression part (`a if c else b`) while a filter goes at the end. Nested loops read left to right like the equivalent for-loops.", "code": {"py": "nums = range(6)\nprint([x * x for x in nums if x % 2 == 0])          # [0, 4, 16]\nprint([\"even\" if x % 2 == 0 else \"odd\" for x in nums][:2])   # ['even','odd']\nprint({x: x * x for x in range(3)})                 # {0:0, 1:1, 2:4}\nprint({len(w) for w in [\"a\", \"bb\", \"cc\"]})          # {1, 2}\ngrid = [[1, 2], [3, 4]]\nprint([v for row in grid for v in row])             # [1, 2, 3, 4]"}, "see": ["#/cheatsheets/python"], "check": "assert [v for row in grid for v in row]==[1,2,3,4] and {x:x*x for x in range(3)}[2]==4"},
    {"id": "pylib-any-all-minmax", "title": "any, all, min, max, sum with generators", "q": ["python any all", "max with key function", "min of empty list error", "sum of list of lists python", "check if all elements satisfy condition"], "tags": "any all min max sum key default generator builtins", "a": "`any(cond for x in it)` and `all(...)` short-circuit; `max(it, key=f)` and `min` pick by a key; pass `default=` to avoid `ValueError` on empty input. `sum(1 for x in it if cond)` counts matches.", "code": {"py": "a = [3, 8, 5]\nprint(any(x > 7 for x in a), all(x > 2 for x in a))   # True True\nprint(max(a, key=lambda x: -x))                       # 3 (smallest via key)\nprint(max([], default=-1))                            # -1\nprint(sum(1 for x in a if x % 2))                     # 2 odd numbers\nprint(max(\"pear\", \"fig\", key=len))                    # pear\nprint(all([]), any([]))                               # True False"}, "more": "- On ties `max` returns the first maximal element.", "cx": "O(n), short-circuit may stop early", "see": ["#/cheatsheets/python"], "check": "assert all([]) and not any([]) and max([],default=-1)==-1 and sum(1 for x in a if x%2)==2"},
    {"id": "pylib-string-to-int-bases", "title": "Convert between number bases and strings", "q": ["binary to decimal python", "int to binary string", "int with base", "convert string to int python", "hex to int python"], "tags": "bin hex oct int base binary decimal convert string format", "a": "`int(\"101\", 2)` parses a string in any base 2-36. `bin(n)`, `hex(n)`, `oct(n)` produce strings with prefixes; `format(n, \"b\")` or `f\"{n:b}\"` leave the prefix off, and `f\"{n:08b}\"` zero-pads.", "code": {"py": "print(int(\"101\", 2), int(\"ff\", 16), int(\"12\"))   # 5 255 12\nprint(bin(10), hex(255))        # 0b1010 0xff\nprint(format(10, \"b\"), f\"{5:08b}\")   # 1010 00000101\nprint(int(\"0b11\", 0))           # 3 (base 0 reads the prefix)\nprint(str(123)[::-1])           # 321\ndigits = [int(c) for c in str(9045)]\nprint(digits)   # [9, 0, 4, 5]"}, "more": "- `int()` raises `ValueError` on invalid text; negative numbers give `-0b...` from `bin`.", "see": ["#/cheatsheets/python"], "check": "assert int(\"101\",2)==5 and format(10,\"b\")==\"1010\" and f\"{5:08b}\"==\"00000101\" and digits==[9,0,4,5]\ntry:\n    int(\"abc\"); assert False\nexcept ValueError: pass"},
    {"id": "pylib-sorted-vs-sort", "title": "sorted vs list.sort and stability", "q": ["sorted vs sort in python", "is python sort stable", "sort in descending order python", "sort strings by length", "sort list without modifying original"], "tags": "sorted sort stable reverse key timsort descending copy in place", "a": "`sorted(x)` returns a new list from any iterable; `a.sort()` sorts a list in place and returns None. Both use Timsort, are stable (equal keys keep their order) and take `key=` and `reverse=True`.", "code": {"py": "a = [\"pear\", \"fig\", \"apple\", \"kiwi\"]\nprint(sorted(a, key=len))             # ['fig','pear','kiwi','apple']  stable\nprint(sorted(a, reverse=True)[0])     # pear\nb = a[:]\nb.sort(key=lambda s: (-len(s), s))\nprint(b)                              # ['apple','kiwi','pear','fig']\nprint(a[0])                           # pear (original untouched by sorted)"}, "more": "- `sorted` accepts strings, tuples, dict keys, sets.\n- Stable sort lets you sort by several keys in separate passes.", "cx": "O(n log n) time, O(n) space; best case O(n) on nearly sorted data", "see": ["#/topic/sorting"], "check": "assert sorted(a,key=len)==[\"fig\",\"pear\",\"kiwi\",\"apple\"] and b==[\"apple\",\"kiwi\",\"pear\",\"fig\"]"}
  );
})();
